"""Named camera moves for a Blender scene, keyed per frame, with lens and shutter settings.

    blender -b scene.blend --factory-startup --python-exit-code 1 --python camera-rig.py -- shots.json out.blend
    python3 camera-rig.py --list

Each shot gets a `<shot> Rig` empty that carries the move and aims with a level horizon (plus any Dutch
roll), and a `<shot> Camera` child that carries only shake. A timeline marker at the shot's first frame
binds its camera. Metres, degrees, frames, Z up. Overwrites the output (and deletes it first, so a failed
run leaves nothing stale) and prints one `CAMERA_RIG {json}` line per shot. A bad plan prints
`camera-rig: error: ...` on stderr and exits 1.
"""

import argparse
import json
import math
import os
import random
import sys
from pathlib import Path

try:
    import bpy
    from mathutils import Euler, Vector
except ImportError:  # `python3 camera-rig.py --list` runs without Blender
    bpy = None

COMMON = {"ease": "ease", "aim": "subject", "aim_to": None, "roll": 0.0, "follow": False, "shake": 0.0,
          "heading": 0.0, "heading_to": None, "distance": 4.0, "distance_to": None,
          "height": 1.4, "height_to": None, "from": None, "to": None}
MOVES = {
    "static": ("Locked off.", {}),
    "dolly": ("Straight push toward the subject (push > 0) or pull back (push < 0).", {"push": 1.5}),
    "orbit": ("Circle the subject from heading to heading_to.", {"heading_to": 90.0}),
    "jib": ("Crane reveal: rise and pull back.", {"distance": 3.0, "distance_to": 7.0, "height": 0.6, "height_to": 4.0}),
    "handheld": ("Hand-held: seeded shake on the camera only.", {"distance": 2.0, "height": 1.6, "shake": 1.0}),
    "dolly-zoom": ("Vertigo: dolly while the focal length keeps the subject's size.", {"distance": 6.0, "distance_to": 3.0}),
}
SENSORS = {"super35": (24.89, 18.67), "full-frame": (36.0, 24.0), "super16": (12.52, 7.42)}
LENS = {"sensor": "super35", "focal": 35.0, "fstop": 2.8, "focus": "subject", "shutter": 180.0, "zoom": None}


class PlanError(ValueError):
    pass


def main():
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else sys.argv[1:]
    if argv == ["--list"]:
        for name, (about, params) in MOVES.items():
            print(json.dumps({"move": name, "about": about, "params": {**COMMON, **params}}))
        print(json.dumps({"lens": LENS, "sensors": list(SENSORS), "ease": ["ease", "linear", "in", "out"]}))
        return
    if bpy is None:
        raise PlanError("run inside Blender: blender -b scene.blend --python camera-rig.py -- shots.json out.blend")
    parser = argparse.ArgumentParser(prog="camera-rig", description=__doc__)
    parser.add_argument("plan", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args(argv)
    if not bpy.data.filepath:
        raise PlanError("no scene is open; run blender -b <scene.blend> ... --python camera-rig.py")
    output = args.output.resolve()
    if output.exists() and output != Path(bpy.data.filepath).resolve():
        output.unlink()  # a failed run must not leave the previous run's file to be rendered
    shots = json.loads(args.plan.read_text()).get("shots") or []
    if not shots:
        raise PlanError("the plan has no shots")
    names = [shot.get("name") for shot in shots]
    if len(set(names)) != len(names) or not all(names):
        raise PlanError("give every shot a unique name")
    ordered = sorted(shots, key=lambda shot: shot.get("start", 0))
    for first, second in zip(ordered, ordered[1:]):
        if second["start"] <= first["end"]:
            raise PlanError("shots %r and %r overlap" % (first["name"], second["name"]))
    scene = bpy.context.scene
    # A rerun on a rigged file replaces the shots this script rigged under the same names, and any it rigged
    # that a new shot overlaps; everything else stays.
    replaced = set(names)
    for marker in [m for m in scene.timeline_markers if m.camera and m.camera.get("camera_rig")]:
        first, last = marker.camera["camera_rig_frames"]
        clash = next((shot["name"] for shot in shots if shot["start"] <= last and first <= shot["end"]), None)
        if marker.name in names or clash:
            if marker.name not in names:
                print("camera-rig: replaced %r (%d-%d), overlapped by %r" % (marker.name, first, last, clash), file=sys.stderr)
            replaced.add(marker.camera["camera_rig"])
            scene.timeline_markers.remove(marker)
    for obj in [o for o in bpy.data.objects if o.get("camera_rig") in replaced]:
        bpy.data.objects.remove(obj)
    others = [m.frame for m in scene.timeline_markers if m.camera and not m.camera.get("camera_rig")]
    collection = bpy.data.collections.get("Camera rigs")
    if collection is None:
        collection = bpy.data.collections.new("Camera rigs")
        scene.collection.children.link(collection)
    for shot in ordered:
        print("CAMERA_RIG " + json.dumps(build(scene, collection, shot)), flush=True)
    # Shutter is render-wide: set it once when every rigged shot agrees, else key each shot's first frame and hold.
    # Keys from earlier runs go first, so a rerun never inherits a stale or moved key.
    rigged = sorted((tuple(m.camera["camera_rig_frames"]), m.camera["camera_rig_shutter"] / 360)  # 180 degrees = half a frame
                    for m in scene.timeline_markers if m.camera and m.camera.get("camera_rig"))
    animation = scene.animation_data
    bag = animation.action.layers[0].strips[0].channelbag(animation.action_slot) if animation and animation.action else None
    for curve in [c for c in (bag.fcurves if bag else []) if c.data_path == "render.motion_blur_shutter"]:
        bag.fcurves.remove(curve)
    scene.render.use_motion_blur = True
    if len({value for _, value in rigged}) == 1 and not others:
        scene.render.motion_blur_shutter = rigged[0][1]
    else:
        for (first, _), value in rigged:
            scene.render.motion_blur_shutter = value
            scene.render.keyframe_insert("motion_blur_shutter", frame=first)
        interpolate(scene, "CONSTANT", "render.motion_blur_shutter")
    scene.frame_start = min([first for (first, _), _ in rigged] + ([scene.frame_start] if others else []))
    scene.frame_end = max([last for (_, last), _ in rigged] + ([scene.frame_end] if others else []))
    scene.frame_set(scene.frame_start)
    bpy.ops.wm.save_as_mainfile(filepath=str(output), copy=True)


def build(scene, collection, shot):
    name, move = shot["name"], shot.get("move")
    if move not in MOVES:
        raise PlanError("%s: unknown move %r; run python3 camera-rig.py --list" % (name, move))
    defaults = {**COMMON, **MOVES[move][1]}
    unknown = set(shot.get("params", {})) - set(defaults)
    if unknown:
        raise PlanError("%s: unknown %s parameter(s) %s; run python3 camera-rig.py --list" % (name, move, ", ".join(sorted(unknown))))
    p = {**defaults, **shot.get("params", {})}
    start, end = int(shot["start"]), int(shot["end"])
    if end <= start:
        raise PlanError("%s: end must come after start" % name)
    frames = list(range(start, end + 1))
    subject, point, centre = shot.get("subject"), None, None
    if isinstance(subject, (list, tuple)):
        subject, point = None, Vector(subject)
    elif subject is not None:
        subject = bpy.data.objects.get(subject)
        if subject is None:
            raise PlanError("%s: no object named %r" % (name, shot["subject"]))
        centre = sum((Vector(c) for c in subject.bound_box), Vector()) / 8
    targets, grounds = [], []  # the subject's centre, and the ground under it, per frame
    for frame in frames:
        scene.frame_set(frame)
        if subject is not None:
            targets.append(subject.matrix_world @ centre)
            grounds.append(Vector((*targets[-1].xy, min((subject.matrix_world @ Vector(c)).z for c in subject.bound_box))))
        elif point is not None:
            targets.append(point)
            grounds.append(Vector((point.x, point.y, 0)))
    u = [ease(i / (len(frames) - 1), p["ease"]) for i in range(len(frames))]
    if p["from"]:
        a, b = Vector(p["from"]), Vector(p["to"] or p["from"])
        positions = [a.lerp(b, t) for t in u]
    elif grounds:
        ends = {key: p[key + "_to"] if p[key + "_to"] is not None else p[key] for key in ("heading", "distance", "height")}
        if "push" in p and p["distance_to"] is None:
            ends["distance"] = p["distance"] - p["push"]
        if min(p["distance"], ends["distance"]) < 0.1:
            raise PlanError("%s: the camera would reach the subject; shorten the push or start further away" % name)
        lerp = lambda key, t: p[key] + (ends[key] - p[key]) * t
        positions = [around(grounds[i if p["follow"] else 0], lerp("heading", t), lerp("distance", t), lerp("height", t))
                     for i, t in enumerate(u)]
    else:
        raise PlanError("%s: give a subject (an object or [x, y, z]), or from/to points" % name)
    aims = aim_points(scene, frames, p["aim"], targets, name)
    if p["aim_to"] is not None:  # move the aim from one target to the other on the shot's ease
        aims = [a.lerp(b, t) for a, b, t in zip(aims, aim_points(scene, frames, p["aim_to"], targets, name), u)]

    rig = bpy.data.objects.new("%s Rig" % name, None)
    rig.empty_display_type, rig.rotation_mode = "ARROWS", "YXZ"
    camera = bpy.data.objects.new("%s Camera" % name, bpy.data.cameras.new(name))
    camera.parent = rig
    camera.rotation_euler = (math.pi / 2, 0, 0)  # the rig looks along +Y with Z up
    collection.objects.link(rig)
    collection.objects.link(camera)
    rig["camera_rig"] = camera["camera_rig"] = name  # what a rerun may replace
    camera["camera_rig_frames"] = [start, end]
    previous = None
    for frame, here, target in zip(frames, positions, aims):
        d = target - here
        # Yaw and pitch at the target, roll only from the plan: the horizon stays level.
        euler = Euler((math.atan2(d.z, d.xy.length), math.radians(p["roll"]), math.atan2(-d.x, d.y)), "YXZ")
        if previous:
            euler.make_compatible(previous)
        rig.location, rig.rotation_euler, previous = here, euler, euler
        rig.keyframe_insert("location", frame=frame)
        rig.keyframe_insert("rotation_euler", frame=frame)
    fps = scene.render.fps / scene.render.fps_base
    if p["shake"]:
        shake(camera, frames, fps, p["shake"], name)
    mark = None
    if targets:  # what focus and the dolly-zoom driver measure to
        mark = bpy.data.objects.new("%s Subject" % name, None)
        mark.empty_display_size = 0.1
        mark.parent = subject
        mark.location = centre if subject is not None else point
        mark["camera_rig"] = name
        collection.objects.link(mark)
    report = lens(scene, camera, shot.get("lens", {}), mark, (targets[0] - positions[0]).length if targets else None, frames, name, move)
    camera["camera_rig_shutter"] = report["shutter_deg"]
    for owner in (rig, camera, camera.data):
        interpolate(owner, "LINEAR")  # keys on every frame: no Bezier overshoot between them
    marker = scene.timeline_markers.new(name, frame=start)
    marker.camera = camera
    if scene.camera is None or start == min(m.frame for m in scene.timeline_markers):
        scene.camera = camera
    peak = max((b - a).length for a, b in zip(positions, positions[1:])) * fps
    return {"shot": name, "move": move, "frames": [start, end], "camera": camera.name, **report,
            "camera_speed_peak_mps": round(peak, 3)}


def aim_points(scene, frames, aim, targets, name):
    """Per frame: the subject, where it starts (locked), a fixed point, or another object's centre."""
    if isinstance(aim, list) and len(aim) == 3:
        return [Vector(aim)] * len(frames)
    if aim in ("subject", "locked") and targets:
        return targets if aim == "subject" else [targets[0]] * len(frames)
    obj = bpy.data.objects.get(aim) if isinstance(aim, str) else None
    if obj is None:
        raise PlanError("%s: aim is subject or locked (both need a subject), an object name or [x, y, z]" % name)
    centre = sum((Vector(c) for c in obj.bound_box), Vector()) / 8
    points = []
    for frame in frames:
        scene.frame_set(frame)
        points.append(obj.matrix_world @ centre)
    return points


def around(ground, heading, distance, height):
    """Heading 0 puts the camera on the subject's -Y side looking +Y; counterclockwise from above."""
    h = math.radians(heading)
    return Vector((ground.x + distance * math.sin(h), ground.y - distance * math.cos(h), ground.z + height))


def shake(camera, frames, fps, amount, name):
    """Seeded hand-held noise (0.4 degrees, 6 mm RMS at 1, 0.3-2.5 Hz) on the camera's local transform only."""
    rng = random.Random(name)
    channels = []
    for _ in range(6):
        waves = [(rng.uniform(0.3, min(2.5, 0.45 * fps)), rng.uniform(0, math.tau)) for _ in range(4)]
        channels.append([amount * sum(math.sin(math.tau * f * i / fps + phase) for f, phase in waves) / math.sqrt(2)
                         for i in range(len(frames))])
    for i, frame in enumerate(frames):
        tilt, roll, pan = (math.radians(0.4) * c[i] for c in channels[:3])
        camera.rotation_euler = (math.pi / 2 + tilt, roll, pan)
        camera.location = [0.006 * c[i] for c in channels[3:]]
        camera.keyframe_insert("location", frame=frame)
        camera.keyframe_insert("rotation_euler", frame=frame)


def lens(scene, camera, spec, mark, distance, frames, name, move):
    unknown = set(spec) - set(LENS)
    if unknown:
        raise PlanError("%s: unknown lens setting(s) %s" % (name, ", ".join(sorted(unknown))))
    spec = {**LENS, **spec}
    if spec["sensor"] not in SENSORS:
        raise PlanError("%s: sensor is one of %s" % (name, ", ".join(SENSORS)))
    if not 0 < spec["shutter"] <= 360:
        raise PlanError("%s: shutter angle is 1-360 degrees" % name)
    data = camera.data
    width, height = SENSORS[spec["sensor"]]
    data.sensor_fit = "HORIZONTAL"
    data.sensor_width, data.sensor_height = width, height
    focal = data.lens = float(spec["focal"])
    if move == "dolly-zoom":
        if mark is None:
            raise PlanError("%s: a dolly zoom needs a subject" % name)
        driver = data.driver_add("lens").driver
        driver.type = "SCRIPTED"
        variable = driver.variables.new()
        variable.name, variable.type = "distance", "LOC_DIFF"
        variable.targets[0].id, variable.targets[1].id = camera, mark
        driver.expression = "%.6f * distance" % (focal / distance)  # lens = k * distance
    if spec["zoom"]:
        if move == "dolly-zoom":
            raise PlanError("%s: the dolly zoom owns the focal length" % name)
        zoom = spec["zoom"]
        at, length = int(zoom.get("at", 0)), max(int(zoom.get("frames", 6)), 1)
        for i, frame in enumerate(frames):
            t = ease(min(max((i - at) / length, 0), 1), "ease")
            data.lens = math.exp(math.log(focal) + (math.log(zoom["to"]) - math.log(focal)) * t)
            data.keyframe_insert("lens", frame=frame)
    data.dof.use_dof = spec["fstop"] is not None and (spec["focus"] != "subject" or mark is not None)
    if data.dof.use_dof:
        data.dof.aperture_fstop = spec["fstop"]
        if spec["focus"] == "subject":
            data.dof.focus_object = mark
        else:
            data.dof.focus_distance = float(spec["focus"])
    return {"sensor": spec["sensor"], "focal_mm": focal, "hfov_deg": round(math.degrees(2 * math.atan(width / 2 / focal)), 2),
            "fstop": spec["fstop"] if data.dof.use_dof else None, "shutter_deg": float(spec["shutter"])}


def interpolate(owner, kind, path=None):
    """Blender 5 slotted actions keep the F-curves in the slot's channel bag."""
    animation = owner.animation_data
    bag = animation.action.layers[0].strips[0].channelbag(animation.action_slot) if animation and animation.action else None
    for curve in [c for c in (bag.fcurves if bag else []) if path in (None, c.data_path)]:
        for point in curve.keyframe_points:
            point.interpolation = kind


def ease(t, kind):
    if kind == "linear":
        return t
    if kind == "ease":
        return 0.5 - 0.5 * math.cos(math.pi * t)
    if kind == "in":
        return 1 - math.cos(math.pi * t / 2)
    if kind == "out":
        return math.sin(math.pi * t / 2)
    raise PlanError("ease is ease, linear, in or out")


if __name__ == "__main__":
    try:
        main()
    except Exception as error:  # Blender exits 0 after a traceback; leave with 1 and say why, on stderr
        if not isinstance(error, (PlanError, json.JSONDecodeError)):
            import traceback

            traceback.print_exc()
        print("camera-rig: error: %s" % error, file=sys.stderr)
        sys.stdout.flush()
        sys.stderr.flush()
        os._exit(1)

"""Download a 3D model, import it into Blender, and report what it contains before you build on it.

    blender -b --factory-startup --python fetch-model.py -- --input URL_OR_FILE --out DIR \\
        [--source z-anatomy | --license L --attribution A] [--find cruciate,meniscus]

--input: .glb, .gltf, .obj, .stl, .fbx, .ply, legacy .vtk, or a .zip holding one. Writes DIR/<name>.blend
(the model, centered, on z=0, and the camera of its still), DIR/<name>.json (source, license,
attribution, object/mesh names, bounds, triangles, materials, --find matches) and DIR/<name>.png, then
prints one ``FETCH_MODEL_JSON `` line (offline: --download-only first). Every failure prints
``fetch-model: error: ...`` and exits non-zero.
"""
import argparse
import hashlib
import http.client
import json
import math
import os
import re
import shlex
import struct
import sys
import urllib.error
import urllib.parse
import urllib.request
import zipfile

FORMATS = ("glb", "gltf", "fbx", "obj", "stl", "ply", "vtk")
USER_AGENT = "Voyager-fetch-model/1.0"
WARNINGS_SUFFIX = ".fetch-warnings.json"
POLY_HAVEN_API = "https://api.polyhaven.com/files/"
OFFLINE_HINT = ("Without network (e.g. Codex's sandbox), run `python3 fetch-model.py --download-only --input URL --out DIR` "
                "with network permission, then pass the file to --input with --source-url URL.")
SOURCES = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "references", "model-sources.json")


class FetchError(Exception):
    pass


def parse_args(argv):
    parser = argparse.ArgumentParser(prog="fetch-model.py", allow_abbrev=False)
    parser.add_argument("--input", required=True, help="URL or file of the model (or a .zip)")
    parser.add_argument("--out", required=True, help="Output directory")
    parser.add_argument("--name", help="Output base name")
    parser.add_argument("--format", choices=FORMATS, help="Format, when the name has none")
    parser.add_argument("--pick", help="In a .zip, the model whose path contains this")
    parser.add_argument("--source", help="Id in references/model-sources.json")
    parser.add_argument("--license", help="e.g. CC-BY-4.0")
    parser.add_argument("--attribution", help="Credit line the license asks for")
    parser.add_argument("--source-url", help="URL to record for a local --input")
    parser.add_argument("--find", default="", help="Comma-separated name terms to look for")
    parser.add_argument("--size", type=float, help="Rescale to this largest side (m)")
    parser.add_argument("--keep-scale", action="store_true", help="Do not scale, center or ground")
    parser.add_argument("--up", choices=("Z", "Y", "-Y", "X", "-X", "-Z"), default="Z", help="Up axis after import")
    parser.add_argument("--no-render", action="store_true", help="Skip the still")
    parser.add_argument("--resolution", type=int, default=1024, help="Still size (px)")
    parser.add_argument("--max-mb", type=float, default=1024, help="Download size limit")
    parser.add_argument("--download-only", action="store_true", help="Download and stop (no Blender)")
    args = parser.parse_args(argv)
    if not all(0 < value < math.inf for value in (1 if args.size is None else args.size, args.resolution, args.max_mb)):
        parser.error("--size, --resolution and --max-mb must be positive numbers")
    if args.name is not None and (not safe_name(args.name) or safe_name(args.name) != args.name):
        parser.error("--name must be a plain file name (letters, digits, . _ -)")
    return args


def script_args():
    return sys.argv[sys.argv.index("--") + 1 :] if "--" in sys.argv else sys.argv[1:]


def is_url(text):
    return urllib.parse.urlparse(text).scheme in ("http", "https")


def file_name_from_url(url):
    name = os.path.basename(urllib.parse.unquote(urllib.parse.urlparse(url).path))
    return safe_name(name) or "model"


def safe_name(name):
    return re.sub(r"[^A-Za-z0-9._-]+", "_", name).strip("._")


class HttpOnlyRedirects(urllib.request.HTTPRedirectHandler):
    """urllib also follows redirects to ftp://; a download may only move to another http(s) URL."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if not is_url(newurl):
            raise urllib.error.HTTPError(newurl, code, f"{msg} - redirect to {newurl!r} refused", headers, fp)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def open_url(url):
    request = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
    try:
        return urllib.request.build_opener(HttpOnlyRedirects).open(request, timeout=60)
    except urllib.error.HTTPError as error:
        raise FetchError(f"HTTP {error.code} {error.reason} for {url}") from None
    except (http.client.HTTPException, ValueError) as error:
        raise FetchError(f"could not request {url} ({error})") from None
    except (urllib.error.URLError, OSError) as error:
        raise FetchError(f"could not reach {url} ({getattr(error, 'reason', error)}). {OFFLINE_HINT}") from None


def http_get(url, destination, max_bytes):
    with open_url(url) as response:
        final_url = response.geturl()
        disposition = response.headers.get("Content-Disposition") or ""
        length = response.headers.get("Content-Length")
        if length and length.isdigit() and int(length) > max_bytes:
            raise FetchError(f"{url} is {int(length) // 2**20} MB, above --max-mb {max_bytes // 2**20}")
        os.makedirs(os.path.dirname(destination), exist_ok=True)
        total = 0
        try:
            with open(destination + ".part", "wb") as handle:
                while chunk := response.read(1 << 20):
                    total += len(chunk)
                    if total > max_bytes:
                        raise FetchError(f"{url} is larger than --max-mb {max_bytes // 2**20}")
                    handle.write(chunk)
        except (OSError, http.client.HTTPException, FetchError) as error:
            if os.path.exists(destination + ".part"):
                os.remove(destination + ".part")
            raise error if isinstance(error, FetchError) else FetchError(f"download of {url} failed: {error}") from None
        os.replace(destination + ".part", destination)
    match = re.search(r'filename\*?=(?:UTF-8\'\')?"?([^";]+)"?', disposition)
    # The URL after redirects: companions and the name resolve against it.
    return (safe_name(urllib.parse.unquote(match.group(1))) if match else None), final_url


def download(url, folder, max_bytes):
    """Download url into folder, with the files a .gltf or .obj references next to it.

    Returns (path, warnings). A glTF buffer is required; textures and OBJ material files are not,
    so a missing one is a warning (the model imports untextured).
    """
    name = file_name_from_url(url)
    path = os.path.join(folder, name)
    served, url = http_get(url, path, max_bytes)
    # Name the file by what it is, so its companions are found: the served name, the redirected
    # URL's, or the format its bytes show (a .gltf saved as "download" would lose its buffer).
    if extension(name) not in FORMATS + ("zip",):
        known = [candidate for candidate in (served, file_name_from_url(url)) if extension(candidate or "") in FORMATS + ("zip",)]
        sniffed = sniff(path)
        renamed = os.path.join(folder, known[0] if known else f"{name}.{sniffed}" if sniffed else name)
        os.replace(path, renamed)
        path = renamed
    warnings = []
    served_at = poly_haven_files(url, warnings) if extension(path) == "gltf" else {}
    for uri, required in companion_uris(path, warnings):
        try:
            target = os.path.join(os.path.dirname(path), *uri_parts(uri))
            base = served_at.get(uri) or urllib.parse.urljoin(url, quote(uri))
            http_get(base, target, max_bytes)
        except FetchError as error:
            if required:
                raise
            warnings.append(f"Could not fetch {uri}: {error}")
            continue
        if extension(uri) == "mtl":
            for texture, _required in companion_uris(target, warnings):
                try:
                    http_get(urllib.parse.urljoin(base, quote(texture)),
                             os.path.join(os.path.dirname(target), *uri_parts(texture)), max_bytes)
                except FetchError as error:
                    warnings.append(f"Could not fetch {texture}: {error}")
    return path, warnings


def poly_haven_files(url, warnings):
    """{uri: url}: Poly Haven serves a glTF's textures from other folders than its URIs name; its API lists them."""
    path = urllib.parse.urlparse(url).path
    match = re.search(r"/ph-assets/Models/gltf/[^/]+/([^/]+)/[^/]+\.gltf$", path)
    if not match:
        return {}
    try:
        with open_url(POLY_HAVEN_API + match.group(1)) as response:
            sizes = json.load(response)["gltf"].values()
        entry = next(size["gltf"] for size in sizes if urllib.parse.urlparse(size["gltf"]["url"]).path == path)
        return {uri: item["url"] for uri, item in entry["include"].items() if is_url(item["url"])}
    except (FetchError, OSError, ValueError, LookupError, TypeError, AttributeError, StopIteration, http.client.HTTPException) as error:
        warnings.append(f"Poly Haven's file list was unreadable ({error}); textures resolve next to the glTF.")
        return {}


def quote(uri):
    return urllib.parse.quote(uri.replace("\\", "/"), safe="/%:@")


def companion_uris(path, warnings):
    """Relative files a model references: [(uri, required)] for .gltf buffers/images, .obj mtllib, .mtl maps.

    An optional file outside the model's folder (an absolute Windows texture path, ../) is skipped with a warning."""
    kind = extension(path)
    if kind == "gltf":
        try:
            with open(path, encoding="utf-8") as handle:
                document = json.load(handle)
        except ValueError as error:
            raise FetchError(f"{os.path.basename(path)} is not valid glTF JSON ({error})") from None
        found = [
            (entry.get("uri"), key == "buffers")
            for key in ("buffers", "images")
            for entry in document.get(key, [])
            if isinstance(entry, dict)
        ]
    elif kind in ("obj", "mtl"):
        pattern = r"^\s*mtllib\s+(.+?)\s*$" if kind == "obj" else r"^\s*(?:map_\w+|bump|disp|decal|norm|refl)\s+(.+?)\s*$"
        with open(path, encoding="utf-8", errors="replace") as handle:
            text = handle.read()
        # An mtllib line can name several libraries; a map line is options (-bm 1) then one file name.
        matches = re.findall(pattern, text, re.MULTILINE)
        found = [(uri, False) for match in matches for uri in ([map_file(match)] if kind == "mtl" else match.split())]
    else:
        return []
    unique = []
    for uri, required in found:
        if uri and not uri.startswith("data:") and not is_url(uri) and uri not in [seen for seen, _ in unique]:
            try:
                uri_parts(uri)
            except FetchError as error:
                if required:
                    raise
                warnings.append(f"Skipped {uri}: {error}")
                continue
            unique.append((uri, required))
    return unique


def map_file(statement):
    words = statement.split()
    while len(words) > 1 and words[0].startswith("-"):
        words.pop(0)
        while len(words) > 1 and re.fullmatch(r"[-+]?[\d.]+(e[-+]?\d+)?|on|off|[rgbmlz]", words[0], re.IGNORECASE):
            words.pop(0)
    return " ".join(words).strip('"')


def uri_parts(uri):
    # A scheme (file:, ftp:) or a //host would make urllib read a local file or another server.
    texts = (uri, urllib.parse.unquote(uri).replace("\\", "/"))
    if any(urllib.parse.urlparse(text).scheme or urllib.parse.urlparse(text).netloc or text.startswith("//") for text in texts):
        raise FetchError(f"the model references a file outside its folder: {uri}")
    parts = [part for part in texts[1].split("/") if part not in ("", ".")]
    # A drive in any part (a/C:/x) makes os.path.join on Windows drop everything before it.
    if not parts or ".." in parts or any(":" in part for part in parts):
        raise FetchError(f"the model references a file outside its folder: {uri}")
    return parts


def extension(path):
    return os.path.splitext(path)[1].lower().lstrip(".")


def sniff(path):
    """The format the file's bytes say it is, or None when they match no supported format."""
    with open(path, "rb") as handle:
        head = handle.read(512)
        handle.seek(0)
        opening = handle.read(1 << 16)
    size = os.path.getsize(path)
    if head.startswith(b"glTF"):
        return "glb"
    if head.startswith(b"PK\x03\x04"):
        return "zip"
    if head.startswith(b"Kaydara FBX Binary"):
        return "fbx"
    if head.startswith(b"# vtk DataFile"):
        return "vtk"
    if head.startswith(b"ply"):
        return "ply"
    text = head.lstrip()
    if text.startswith(b"{") and b'"asset"' in opening:
        return "gltf"
    if len(head) >= 84:
        (triangles,) = struct.unpack("<I", head[80:84])
        if size == 84 + 50 * triangles and triangles > 0:
            return "stl"
    if text.lower().startswith(b"solid") and b"facet" in opening.lower():
        return "stl"
    if text.startswith(b"; FBX") or b"FBXHeaderExtension" in head:
        return "fbx"
    if re.search(rb"(^|\n)\s*(v|vn|vt|f|o|g|mtllib|usemtl)\s", opening):
        return "obj"
    return None


def detect_format(path, override=None):
    """The format to import: the extension (or --format) when the bytes agree with it."""
    claimed = override or extension(path)
    found = sniff(path)
    if claimed not in FORMATS + ("zip",):
        if found:
            return found
        raise FetchError(
            f"unsupported format {claimed or '(no extension)'!r} for {os.path.basename(path)}; "
            f"supported: {', '.join(FORMATS)}, or a .zip holding one"
        )
    if found != claimed:
        with open(path, "rb") as handle:
            start = handle.read(40)
        raise FetchError(
            f"{os.path.basename(path)} is not a valid {claimed.upper()} file (it starts with {start!r}); "
            "the download may be an error page, or the file is corrupt"
        )
    return claimed


def extract(archive, folder, max_bytes, pick=None):
    """Extract a zip and return (model path, candidates): the --pick match, else the preferred format."""
    try:
        bundle = zipfile.ZipFile(archive)
    except zipfile.BadZipFile:
        raise FetchError(f"{os.path.basename(archive)} is not a valid zip archive") from None
    root = os.path.realpath(folder)
    with bundle:
        if sum(member.file_size for member in bundle.infolist()) > 4 * max_bytes:
            raise FetchError(f"{os.path.basename(archive)} unpacks to more than 4 x --max-mb")
        for member in bundle.infolist():
            target = os.path.realpath(os.path.join(folder, member.filename))
            if not target.startswith(root + os.sep):
                raise FetchError(f"zip entry escapes the output folder: {member.filename}")
        bundle.extractall(folder)
        names = [
            name for name in bundle.namelist()
            if extension(name) in FORMATS and not name.startswith("__MACOSX/") and not name.endswith("/")
        ]
    if not names:
        raise FetchError(f"{os.path.basename(archive)} holds no supported model ({', '.join(FORMATS)})")
    if pick:
        matches = [name for name in names if pick.lower() in name.lower()]
        if not matches:
            raise FetchError(f"no model in {os.path.basename(archive)} matches --pick {pick!r}; it holds: {', '.join(names)}")
        names = matches
    ranked = sorted(names, key=lambda name: (FORMATS.index(extension(name)), -os.path.getsize(os.path.join(folder, name))))
    return os.path.join(folder, ranked[0]), ranked


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def registry_entry(source_id):
    try:
        with open(SOURCES, encoding="utf-8") as handle:
            sources = json.load(handle)["sources"]
    except (OSError, ValueError, KeyError) as error:
        raise FetchError(f"could not read the model sources at {SOURCES} ({error})") from None
    for entry in sources:
        if entry["id"] == source_id:
            return entry
    raise FetchError(f"unknown --source {source_id!r}; ids: {', '.join(entry['id'] for entry in sources)}")


def provenance(args, url, path, fmt):
    entry = registry_entry(args.source) if args.source else {}
    per_model = entry.get("license", "").startswith("Per ")
    return {
        "input": args.input,
        "url": url,
        "file": os.path.abspath(path),
        "format": fmt,
        "bytes": os.path.getsize(path),
        "sha256": sha256(path),
        "sourceId": entry.get("id"),
        "sourceName": entry.get("name"),
        # Sources that license each model separately ("Per model; ...") leave both to --license/--attribution.
        "license": args.license or (None if per_model else entry.get("license")),
        "attribution": args.attribution or (None if per_model else entry.get("attribution")),
    }


def resolve_input(args):
    """Download or locate the model: {path, format, url, candidates (other models in a zip), warnings}."""
    downloads = os.path.join(os.path.abspath(args.out), "downloads")
    warnings = []
    if is_url(args.input):
        path, warnings = download(args.input, downloads, int(args.max_mb * 2**20))
        url = args.input
    else:
        path = os.path.abspath(os.path.expanduser(args.input))
        if not os.path.isfile(path):
            raise FetchError(f"no such file: {path}")
        url = args.source_url
        # A --download-only step leaves its warnings beside the file.
        if os.path.isfile(path + WARNINGS_SUFFIX):
            with open(path + WARNINGS_SUFFIX, encoding="utf-8") as handle:
                warnings = [str(warning) for warning in json.load(handle)]
    fmt = detect_format(path, args.format)
    candidates = []
    if fmt == "zip":
        folder = os.path.join(downloads, safe_name(os.path.splitext(os.path.basename(path))[0]) + "_files")
        path, candidates = extract(path, folder, int(args.max_mb * 2**20), args.pick)
        fmt = detect_format(path, args.format)
    for uri, required in ([] if is_url(args.input) and not candidates else companion_uris(path, warnings)):
        if not os.path.isfile(os.path.join(os.path.dirname(path), *uri_parts(uri))):
            if required:
                raise FetchError(f"{os.path.basename(path)} references {uri}, which is not next to it")
            warnings.append(f"{os.path.basename(path)} references {uri}, which is not next to it.")
    return {"path": path, "format": fmt, "url": url, "candidates": candidates, "warnings": warnings}


def run_blender(args, found):
    path, fmt, url, candidates = found["path"], found["format"], found["url"], found["candidates"]
    import bpy
    from mathutils import Matrix, Vector

    bpy.ops.wm.read_factory_settings(use_empty=True)
    before = set(bpy.data.objects)
    try:
        import_file(bpy, path, fmt)
    except RuntimeError as error:
        raise FetchError(f"Blender could not import {os.path.basename(path)} as {fmt.upper()}: {str(error).strip()}") from None
    imported = [obj for obj in bpy.data.objects if obj not in before]
    meshes = [obj for obj in imported if obj.type == "MESH" and obj.data.polygons]
    if not meshes:
        raise FetchError(f"{os.path.basename(path)} imported no mesh geometry ({len(imported)} object(s))")
    for obj in [obj for obj in imported if obj.type in ("CAMERA", "LIGHT")]:
        imported.remove(obj)
        bpy.data.objects.remove(obj)

    name = args.name or safe_name(os.path.splitext(os.path.basename(path))[0]) or "model"
    root = bpy.data.objects.new(name, None)
    bpy.context.scene.collection.objects.link(root)
    for obj in imported:
        if obj.parent is None:
            world = obj.matrix_world.copy()
            obj.parent = root
            obj.matrix_world = world
    bpy.context.view_layer.update()
    original = world_bounds(meshes, Vector)
    rotation = up_rotation(args.up, Matrix)
    root.matrix_world = rotation
    bpy.context.view_layer.update()
    low, high = world_bounds(meshes, Vector)
    largest = max(high - low)
    scale = 1.0
    if not args.keep_scale and largest > 0:
        scale = (args.size or largest) / largest
        center = (low + high) / 2
        offset = Vector((-center.x * scale, -center.y * scale, -low.z * scale))
        root.matrix_world = Matrix.Translation(offset) @ Matrix.Scale(scale, 4) @ rotation
        bpy.context.view_layer.update()
        low, high = world_bounds(meshes, Vector)

    try:
        bpy.ops.file.pack_all()
    except RuntimeError as error:
        print(f"fetch-model: warning: could not pack every texture: {error}")
    out = os.path.abspath(args.out)
    os.makedirs(out, exist_ok=True)
    blend = os.path.join(out, name + ".blend")

    report = {
        "source": provenance(args, url, path, fmt),
        "blend": blend,
        "still": None,
        "report": os.path.join(out, name + ".json"),
        "blender": bpy.app.version_string,
        "root": root.name,
        "normalization": {
            "centered": not args.keep_scale,
            "up": args.up,
            "scale": scale,
            "originalDimensions": rounded(original[1] - original[0]),
        },
        "bounds": {"min": rounded(low), "max": rounded(high), "dimensions": rounded(high - low)},
        "totals": {},
        "objects": [],
        "materials": [],
        "matches": {},
        "archiveCandidates": candidates[:50],
        "warnings": list(found["warnings"]),
    }
    materials = {}
    triangles_total = vertices_total = 0
    for obj in sorted(imported, key=lambda item: item.name):
        entry = {"name": obj.name, "type": obj.type, "parent": obj.parent.name if obj.parent else None}
        if obj.type == "MESH":
            mesh = obj.data
            mesh.calc_loop_triangles()
            low_o, high_o = world_bounds([obj], Vector)
            names = [slot.material.name for slot in obj.material_slots if slot.material]
            entry.update(
                mesh=mesh.name,
                vertices=len(mesh.vertices),
                triangles=len(mesh.loop_triangles),
                materials=names,
                bounds={"min": rounded(low_o), "max": rounded(high_o)},
            )
            triangles_total += len(mesh.loop_triangles)
            vertices_total += len(mesh.vertices)
            for material in names:
                materials.setdefault(material, []).append(obj.name)
        report["objects"].append(entry)
    for material_name, users in sorted(materials.items()):
        material = bpy.data.materials[material_name]
        textures = sorted({
            node.image.name for node in (material.node_tree.nodes if material.node_tree else [])
            if node.type == "TEX_IMAGE" and node.image
        })
        report["materials"].append({"name": material_name, "objects": len(users), "textures": textures})
    report["totals"] = {
        "objects": len(report["objects"]),
        "meshes": len(meshes),
        "vertices": vertices_total,
        "triangles": triangles_total,
        "materials": len(materials),
    }
    for term in [term.strip() for term in args.find.split(",") if term.strip()]:
        report["matches"][term] = sorted({
            entry["name"] for entry in report["objects"]
            if any(term.lower() in (value or "").lower() for value in [entry["name"], entry.get("mesh")] + entry.get("materials", []))
        })
    if not report["source"]["license"]:
        report["warnings"].append("License unknown: pass --license and --attribution from the model's page."
                                  if args.source else "License unknown: pass --source or --license and confirm it allows this use.")
    if report["source"]["license"] and not report["source"]["attribution"]:
        report["warnings"].append("No attribution recorded: pass --attribution with the credit the license asks for.")
    if not any(entry["textures"] for entry in report["materials"]):
        report["warnings"].append("No textures: give it materials before rendering (fetch-material.py).")
    if not url:
        report["warnings"].append("No source URL recorded: pass --source-url for a model downloaded separately.")
    if not (args.size or args.keep_scale or 0.005 < max(high - low) < 20):
        report["warnings"].append("Largest side under 5 mm or over 20 m: if the file is in mm or cm, pass --size <real m>.")
    report["warnings"] += [f"No object or mesh name contains {term!r}." for term, found in report["matches"].items() if not found]

    if not args.no_render:
        report["still"] = render_still(bpy, Vector, low, high, os.path.join(out, name + ".png"), args.resolution)
    # Saved after the still, so a later preview has its camera.
    bpy.ops.wm.save_as_mainfile(filepath=blend, compress=True)
    with open(report["report"], "w", encoding="utf-8") as handle:
        json.dump(report, handle, indent=2)
    return report


def import_file(bpy, path, fmt):
    if fmt in ("glb", "gltf"):
        bpy.ops.import_scene.gltf(filepath=path)
    elif fmt == "fbx":
        bpy.ops.import_scene.fbx(filepath=path)
    elif fmt == "obj":
        bpy.ops.wm.obj_import(filepath=path)
    elif fmt == "stl":
        bpy.ops.wm.stl_import(filepath=path)
    elif fmt == "ply":
        bpy.ops.wm.ply_import(filepath=path)
    elif fmt == "vtk":
        sys.dont_write_bytecode = True
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        from legacy_vtk import read_vtk

        try:
            points, faces = read_vtk(path)
        except (ValueError, IndexError, struct.error) as error:
            raise FetchError(f"cannot read {os.path.basename(path)} as a VTK surface: {error}") from None
        name = os.path.splitext(os.path.basename(path))[0]
        mesh = bpy.data.meshes.new(name)
        mesh.from_pydata(points, [], faces)
        mesh.validate()
        mesh.update()
        obj = bpy.data.objects.new(name, mesh)
        bpy.context.scene.collection.objects.link(obj)
        for polygon in mesh.polygons:
            polygon.use_smooth = True


def up_rotation(axis, Matrix):
    """Rotation that turns the file's up axis into +Z."""
    angle, around = {"Z": (0, "X"), "Y": (90, "X"), "-Y": (-90, "X"), "X": (-90, "Y"), "-X": (90, "Y"), "-Z": (180, "X")}[axis]
    return Matrix.Rotation(math.radians(angle), 4, around)


def world_bounds(objects, Vector):
    corners = [obj.matrix_world @ Vector(corner) for obj in objects for corner in obj.bound_box]
    return (
        Vector([min(corner[i] for corner in corners) for i in range(3)]),
        Vector([max(corner[i] for corner in corners) for i in range(3)]),
    )


def rounded(vector):
    return [round(value, 5) for value in vector]


def render_still(bpy, Vector, low, high, filepath, resolution):
    """A three-quarter view of the whole model in Workbench (fast, shows shape, textures and colors)."""
    scene = bpy.context.scene
    center = (low + high) / 2
    radius = max((high - low).length / 2, 1e-6)
    camera = bpy.data.objects.new("fetch-model camera", bpy.data.cameras.new("fetch-model camera"))
    scene.collection.objects.link(camera)
    camera.data.lens = 50
    camera.data.clip_start = radius / 1000
    camera.data.clip_end = radius * 100
    direction = Vector((1.0, -1.6, 0.9)).normalized()
    camera.rotation_euler = (-direction).to_track_quat("-Z", "Y").to_euler()
    corners = [Vector((x, y, z)) for x in (low.x, high.x) for y in (low.y, high.y) for z in (low.z, high.z)]
    scene.render.resolution_x = scene.render.resolution_y = resolution
    scene.render.resolution_percentage = 100
    bpy.context.view_layer.update()
    fitted, _scale = camera.camera_fit_coords(bpy.context.evaluated_depsgraph_get(), [c for v in corners for c in v])
    # Step back a quarter of the fitted distance for a margin in frame.
    camera.location = fitted + direction * max((fitted - center).dot(direction), radius) * 0.25
    scene.camera = camera
    scene.render.engine = "BLENDER_WORKBENCH"
    scene.world = scene.world or bpy.data.worlds.new("fetch-model world")
    scene.world.color = (0.42, 0.44, 0.47)
    shading = scene.display.shading
    shading.light = "STUDIO"
    shading.color_type = "TEXTURE"
    shading.show_cavity = True
    shading.show_object_outline = True
    scene.render.film_transparent = False
    scene.render.image_settings.file_format = "PNG"
    scene.render.filepath = filepath
    bpy.ops.render.render(write_still=True)
    return filepath


def summary(report):
    names = [entry["name"] for entry in report["objects"] if entry["type"] == "MESH"]
    keys = ("blend", "report", "still", "totals", "matches", "warnings")
    return {**{key: report[key] for key in keys}, "license": report["source"]["license"],
            "attribution": report["source"]["attribution"], "dimensions": report["bounds"]["dimensions"],
            "meshes": names[:40], "moreMeshes": max(0, len(names) - 40)}


def main():
    args = parse_args(script_args())
    try:
        if args.source:
            registry_entry(args.source)
        if args.download_only:
            if not is_url(args.input):
                raise FetchError("--download-only needs a URL for --input")
            found = resolve_input(args)
            if found["warnings"]:
                with open(found["path"] + WARNINGS_SUFFIX, "w", encoding="utf-8") as handle:
                    json.dump(found["warnings"], handle)
            print("FETCH_MODEL_DOWNLOAD " + json.dumps({
                "file": found["path"], "format": found["format"], "url": found["url"],
                "archiveCandidates": found["candidates"], "warnings": found["warnings"],
            }))
            # Every option but the download's own carries over, so the import honors the original request.
            dropped, carried, skip = {"--download-only": 0, "--input": 1, "--out": 1, "--source-url": 1, "--pick": 1}, [], 0
            for token in script_args():
                flag = token.split("=", 1)[0]
                if skip or flag in dropped:
                    skip = skip - 1 if skip else (0 if "=" in token else dropped[flag])
                    continue
                carried.append(token)
            command = ["blender", "-b", "--factory-startup", "--python", os.path.abspath(__file__), "--",
                       "--input", found["path"], "--source-url", found["url"], "--out", os.path.abspath(args.out)]
            print("Next: " + " ".join(shlex.quote(part) for part in command + carried))
            return 0
        try:
            import bpy  # noqa: F401
        except ImportError:
            raise FetchError("run this under Blender: blender -b --factory-startup --python fetch-model.py -- ...") from None
        report = run_blender(args, resolve_input(args))
        print("FETCH_MODEL_JSON " + json.dumps(summary(report)))
        return 0
    except FetchError as error:
        print(f"fetch-model: error: {error}", file=sys.stderr)
        return 1
    except Exception as error:  # noqa: BLE001 - Blender exits 0 after an uncaught script error.
        import traceback

        traceback.print_exc()
        print(f"fetch-model: error: {type(error).__name__}: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    code = main()
    sys.stdout.flush()
    sys.stderr.flush()
    if code:
        # Blender keeps running (and exits 0) after a --python script returns; leave with the code.
        os._exit(code)

