"""Read the surface of a legacy VTK POLYDATA file (ASCII or BINARY), which Blender cannot import.

fetch-model.py uses it; errors are ValueError with a message naming what is wrong.
"""
import os
import struct

FIELD_TYPES = {
    "float": "f", "double": "d", "int": "i", "unsigned_int": "I", "long": "q", "unsigned_long": "Q",
    "short": "h", "unsigned_short": "H", "char": "b", "unsigned_char": "B", "vtkidtype": "i",
}


def read_vtk(path):
    """Points and faces of a legacy VTK POLYDATA file (ASCII or BINARY; polygons and triangle strips)."""
    with open(path, "rb") as handle:
        data = handle.read()
    lines = data.split(b"\n", 4)
    if len(lines) < 5 or not lines[0].startswith(b"# vtk DataFile"):
        raise ValueError(f"{os.path.basename(path)} is not a legacy VTK file")
    binary = lines[2].strip().upper() == b"BINARY"
    if not lines[3].strip().upper().startswith(b"DATASET POLYDATA"):
        dataset = lines[3].strip().decode("ascii", "replace")
        raise ValueError(f"{os.path.basename(path)} holds {dataset}; only POLYDATA surfaces are supported")
    reader = _VtkReader(data, len(b"\n".join(lines[:4])) + 1, binary)
    points, faces = [], []
    while True:
        header = reader.header()
        if header is None:
            break
        keyword = header[0].upper()
        if keyword == "POINTS":
            count, kind = int(header[1]), header[2].lower()
            flat = reader.values(3 * count, "d" if kind == "double" else "f")
            points = [tuple(flat[i : i + 3]) for i in range(0, len(flat), 3)]
        elif keyword in ("POLYGONS", "TRIANGLE_STRIPS", "VERTICES", "LINES"):
            cells = reader.cells(int(header[1]), int(header[2]))
            if keyword == "POLYGONS":
                faces += [cell for cell in cells if len(cell) >= 3]
            elif keyword == "TRIANGLE_STRIPS":
                faces += strip_triangles(cells)
        elif keyword == "METADATA":
            reader.skip_block()
        elif keyword == "FIELD":
            reader.skip_field(int(header[2]))
        elif keyword in ("POINT_DATA", "CELL_DATA"):
            break
        else:
            raise ValueError(f"unsupported VTK section {keyword} in {os.path.basename(path)}")
    if not points or not faces:
        raise ValueError(f"{os.path.basename(path)} has no surface (no points or faces)")
    used = [index for face in faces for index in face]
    if min(used) < 0 or max(used) >= len(points):
        raise ValueError(f"{os.path.basename(path)} is corrupt: a face uses a point outside the {len(points)} it defines")
    return points, faces


def strip_triangles(strips):
    triangles = []
    for strip in strips:
        for i in range(len(strip) - 2):
            a, b, c = strip[i], strip[i + 1], strip[i + 2]
            if len({a, b, c}) == 3:
                triangles.append((a, b, c) if i % 2 == 0 else (b, a, c))
    return triangles


class _VtkReader:
    def __init__(self, data, offset, binary):
        self.data, self.offset, self.binary = data, offset, binary

    def header(self):
        while self.offset < len(self.data):
            end = self.data.find(b"\n", self.offset)
            end = len(self.data) if end < 0 else end
            line = self.data[self.offset : end].strip()
            self.offset = end + 1
            if line:
                return line.decode("ascii", "replace").split()
        return None

    def skip_block(self):
        """Skip a METADATA block: text lines up to the first blank one."""
        while self.offset < len(self.data):
            end = self.data.find(b"\n", self.offset)
            end = len(self.data) if end < 0 else end
            line, self.offset = self.data[self.offset : end].strip(), end + 1
            if not line:
                return

    def skip_field(self, arrays):
        """Skip a FIELD's arrays (`name components tuples type` then the values), e.g. VTK 9's TimeValue."""
        for _ in range(arrays):
            header = self.header()
            if header and header[0].upper() == "METADATA":
                self.skip_block()
                header = self.header()
            if not header or len(header) < 4 or header[3].lower() not in FIELD_TYPES:
                raise ValueError(f"unsupported VTK FIELD array {' '.join(header or [])!r}")
            self.values(int(header[1]) * int(header[2]), FIELD_TYPES[header[3].lower()])

    def tokens(self, count):
        found = []
        while len(found) < count:
            header = self.header()
            if header is None:
                raise ValueError("VTK file ends early (truncated or corrupt)")
            found += header
        if len(found) != count:
            raise ValueError("VTK data does not line up with its section counts (corrupt file)")
        return found

    def values(self, count, kind):
        if not self.binary:
            try:
                return [float(token) if kind in "fd" else int(token) for token in self.tokens(count)]
            except ValueError:
                raise ValueError("VTK file has a non-numeric value where numbers belong (corrupt)") from None
        size = struct.calcsize(">" + kind)
        end = self.offset + count * size
        if end > len(self.data):
            raise ValueError("VTK file ends early (truncated or corrupt)")
        values = list(struct.unpack(f">{count}{kind}", self.data[self.offset : end]))
        self.offset = end
        return values

    def cells(self, first, second):
        """Old layout: `KEY cells size` then size ints (n, ids...); 5.x: OFFSETS and CONNECTIVITY arrays."""
        saved = self.offset
        header = self.header()
        if header and header[0].upper() == "OFFSETS":
            offsets = self.values(first, "q" if "64" in header[1] else "i")
            header = self.header()
            if not header or header[0].upper() != "CONNECTIVITY":
                raise ValueError("VTK OFFSETS without CONNECTIVITY (corrupt file)")
            ids = self.values(second, "q" if "64" in header[1] else "i")
            return [ids[offsets[i] : offsets[i + 1]] for i in range(first - 1)]
        self.offset = saved
        flat = self.values(second, "i")
        cells, index = [], 0
        for _ in range(first):
            if index >= len(flat):
                raise ValueError("VTK cell list is shorter than its count (corrupt file)")
            count = flat[index]
            cells.append(flat[index + 1 : index + 1 + count])
            index += 1 + count
        return cells

"""Render each light alone, then all together, into one labelled contact strip, to name the light behind
a spill, washout or colour cast before changing anything.

    blender -b scene.blend --python-exit-code 1 --python light-solo.py -- --out review/lights.png \\
        [--percent 50] [--samples 32]

Sources are every render-visible light object, every emissive material on a render-visible object (a
flame, a screen, a bulb mesh: labelled ``glow:<material>``, or ``group:<node group>`` for an emissive node
group several materials share) and the world (``world``); a light named like another pass is
labelled ``light:<name>``. Each pass keeps the scene's engine, camera, exposure and view transform, so the
tiles compare directly; OUT holds the tiles, all first, and OUT-<n>-<name>.png each pass. The .blend
file is not changed.

Output is one ``LIGHT_SOLO <name>:`` line per pass (share of the light, clipped pixels, colour cast), a
``LIGHT_SOLO_SUSPECTS`` line naming the source that leads each problem and a ``LIGHT_SOLO_JSON`` line
with every number. Every failure prints ``light-solo: error: ...`` and exits non-zero.
"""
import argparse
import json
import os
import re
import sys
from collections import Counter

sys.dont_write_bytecode = True
CLIPPED = 0.98  # display value of a blown-out channel
WASHOUT = 0.01  # share of blown-out pixels in the full render that reads as washed out
CAST = 0.15  # (red - blue) / brightness beyond which a render reads warm or cool
COLUMNS = 3
GAP = 8


class SoloError(Exception):
    pass


class Parser(argparse.ArgumentParser):
    def error(self, message):
        raise SoloError(message)


def parse_args(argv):
    parser = Parser(prog="light-solo.py", allow_abbrev=False)
    parser.add_argument("--out", required=True, help="contact strip PNG; each pass is written next to it")
    parser.add_argument("--percent", type=int, default=50, help="render size as a percentage of the scene's")
    parser.add_argument("--samples", type=int, help="render samples per pass (default: the scene's)")
    args = parser.parse_args(argv)
    if not 1 <= args.percent <= 100:
        raise SoloError("--percent must be 1-100")
    if args.samples is not None and args.samples < 1:
        raise SoloError("--samples must be at least 1")
    if not args.out.lower().endswith(".png"):
        raise SoloError("--out must be a .png path")
    return args


def main(argv):
    try:
        import bpy
        import numpy as np
    except ImportError:
        raise SoloError("run this under Blender: blender -b scene.blend --python light-solo.py -- --out review/lights.png")
    args = parse_args(argv)
    scene = bpy.context.scene
    if scene.camera is None:
        raise SoloError("the scene has no camera")
    sources = find_sources(scene)
    if not sources:
        raise SoloError("the scene has no light, emissive material or lit world")
    configure(scene, args)
    stem = os.path.splitext(os.path.abspath(args.out))[0]
    os.makedirs(os.path.dirname(stem), exist_ok=True)
    passes = [("all", None)] + [(name, name) for name in sources]
    tiles, report = [], {"strip": stem + ".png", "passes": {}}
    for index, (label, only) in enumerate(passes):
        for name, (switch, _) in sources.items():
            switch(only is None or name == only)
        path = f"{stem}-{index}-{re.sub(r'[^A-Za-z0-9_-]+', '-', label).strip('-') or 'light'}.png"
        scene.render.stamp_note_text = label if only is None else f"solo: {label}"
        scene.render.filepath = path
        bpy.ops.render.render(write_still=True)
        rgb = load(bpy, np, path)
        tiles.append(rgb)
        report["passes"][label] = {"file": path, **measure(np, rgb[label_rows(scene):])}
    for switch, _ in sources.values():
        switch(True)
    solo_total = sum(report["passes"][name]["light"] for name in sources) or 1e-9
    for name, (_, kind) in sources.items():
        report["passes"][name].update(kind=kind, share=report["passes"][name]["light"] / solo_total)
    report["suspects"] = suspects(report["passes"], list(sources))
    save(bpy, np, strip(np, tiles), report["strip"])
    print("\n".join(pass_line(name, entry) for name, entry in report["passes"].items()), flush=True)
    print("LIGHT_SOLO_SUSPECTS " + "; ".join(f"{problem}: {text}" for problem, text in report["suspects"].items()), flush=True)
    print("LIGHT_SOLO_JSON " + json.dumps(report), flush=True)


def find_sources(scene):
    """{label: (switch(on), kind)} for each light object, emissive material and the world."""
    sources = {}
    layers = [layer.layer_collection for layer in scene.view_layers if layer.use]
    shown = sorted((thing for thing in set().union(*map(rendered_objects, layers)) if not thing.hide_render), key=lambda thing: thing.name)
    for thing in shown:
        if thing.type == "LIGHT":
            # "all", "world", "glow:..." and "group:..." name the other passes; "light:..." keeps the prefixed unique.
            taken = thing.name.casefold() in ("all", "world") or thing.name.startswith(("glow:", "group:", "light:"))
            sources["light:" + thing.name if taken else thing.name] = (lambda on, thing=thing: setattr(thing, "hide_render", not on), "light")
    materials = {slot.material for thing in shown for slot in thing.material_slots if slot.material}
    found = {material: [socket for socket in emission_sockets(material.node_tree) if socket.is_linked or socket.default_value > 0]
             for material in sorted(materials, key=lambda material: material.name)}
    # A node group's sockets are shared by every material using it: switching them per material would let one
    # material's pass turn the other's glow off, so a group used by several materials is a source of its own.
    users = Counter(pointer for sockets in found.values() for pointer in {socket.as_pointer() for socket in sockets})
    groups = {}
    for material, sockets in found.items():
        own = [socket for socket in sockets if users[socket.as_pointer()] == 1]
        if own:
            sources["glow:" + material.name] = (dimmer(own), "emission")
        for socket in sockets:
            if users[socket.as_pointer()] > 1:
                groups.setdefault(socket.id_data.name, {})[socket.as_pointer()] = socket
    for name, sockets in sorted(groups.items()):
        sources["group:" + name] = (dimmer(list(sockets.values())), "emission")
    world = scene.world
    if world and world.use_nodes:
        sockets = [node.inputs["Strength"] for node in world.node_tree.nodes if node.type == "BACKGROUND"]
        sockets = [socket for socket in sockets if socket.is_linked or socket.default_value > 0]
        if sockets:
            sources["world"] = (dimmer(sockets), "world")
    return sources


def rendered_objects(layer):
    """Objects in a view layer's collections that render: an excluded or render-hidden collection hides its
    objects and children, though they stay in scene.objects."""
    if layer.exclude or layer.collection.hide_render:
        return set()
    return set(layer.collection.objects).union(*map(rendered_objects, layer.children))


def emission_sockets(tree):
    if tree is None:
        return []
    found = []
    for node in tree.nodes:
        colour = node.inputs.get("Emission Color")
        if node.type == "BSDF_PRINCIPLED" and (colour.is_linked or max(colour.default_value[:3]) > 0):
            found.append(node.inputs["Emission Strength"])
        if node.type == "EMISSION":
            found.append(node.inputs["Strength"])
        if node.type == "GROUP":
            found += emission_sockets(node.node_tree)
    return found


def dimmer(sockets):
    """Switches the sockets off (strength 0, incoming links muted) and back to their saved state."""
    saved = [(socket, socket.default_value, [(link, link.is_muted) for link in socket.links]) for socket in sockets]

    def switch(on):
        for socket, value, links in saved:
            socket.default_value = value if on else 0.0
            for link, muted in links:
                link.is_muted = muted if on else True

    return switch


def configure(scene, args):
    scene.render.resolution_percentage = args.percent
    if args.samples and scene.render.engine == "CYCLES":
        scene.cycles.samples = args.samples
    if args.samples and scene.render.engine != "CYCLES":
        scene.eevee.taa_render_samples = args.samples
    scene.render.image_settings.file_format = "PNG"
    scene.render.image_settings.color_mode = "RGB"
    scene.render.image_settings.color_depth = "8"
    # The pass label is burnt into each tile's top-left corner by Blender's stamp.
    scene.render.use_stamp = True
    for name in dir(scene.render):
        if name.startswith("use_stamp_"):
            setattr(scene.render, name, False)
    scene.render.use_stamp_note = True
    scene.render.stamp_font_size = max(12, scene.render.resolution_y * args.percent // 100 // 24)


def label_rows(scene):
    """Rows at the top covered by the stamped label, left out of the measurements."""
    return round(scene.render.stamp_font_size * 1.6)


def load(bpy, np, path):
    image = bpy.data.images.load(path, check_existing=False)
    width, height = image.size
    pixels = np.empty(width * height * 4, dtype=np.float32)
    image.pixels.foreach_get(pixels)
    bpy.data.images.remove(image)
    return np.ascontiguousarray(pixels.reshape(height, width, 4)[::-1, :, :3])


def measure(np, rgb):
    linear = np.where(rgb <= 0.04045, rgb / 12.92, ((rgb + 0.055) / 1.055) ** 2.4)
    red, green, blue = (float(linear[:, :, channel].mean()) for channel in range(3))
    light = 0.2126 * red + 0.7152 * green + 0.0722 * blue
    return {
        "light": light,
        "clipped": float((rgb.max(axis=2) >= CLIPPED).mean()),
        "cast": (red - blue) / max(light, 1e-4),
    }


def suspects(passes, sources):
    whole = passes["all"]
    strongest = max(sources, key=lambda name: passes[name]["share"])
    found = {"strongest": f"{strongest} ({passes[strongest]['share']:.0%} of the light)"}
    if whole["clipped"] > WASHOUT:
        # The source that blows out most pixels alone; when none does, the light adds up, so the strongest.
        worst = max(sources, key=lambda name: (passes[name]["clipped"], passes[name]["share"]))
        found["washout"] = f"{worst} ({whole['clipped']:.1%} clipped together, {passes[worst]['clipped']:.1%} alone)"
    if abs(whole["cast"]) > CAST:
        sign = 1 if whole["cast"] > 0 else -1
        worst = max(sources, key=lambda name: passes[name]["share"] * passes[name]["cast"] * sign)
        found["cast"] = f"{worst} ({cast_text(passes[worst]['cast'])} alone, {cast_text(whole['cast'])} together)"
    return found


def cast_text(cast):
    if abs(cast) <= CAST:
        return "neutral"
    return f"{'warm' if cast > 0 else 'cool'} {cast:+.2f}"


def pass_line(name, entry):
    share = f"{entry['share']:.0%} of the light, " if "share" in entry else ""
    return f"LIGHT_SOLO {name}: {share}clipped {entry['clipped']:.1%}, cast {cast_text(entry['cast'])}"


def strip(np, tiles):
    height, width = tiles[0].shape[:2]
    rows = [tiles[start:start + COLUMNS] for start in range(0, len(tiles), COLUMNS)]
    white = np.ones((height, GAP, 3), dtype=np.float32)
    lines = []
    for row in rows:
        row = row + [np.ones((height, width, 3), dtype=np.float32)] * (min(COLUMNS, len(tiles)) - len(row))
        lines.append(np.concatenate([part for tile in row for part in (tile, white)][:-1], axis=1))
    gap = np.ones((GAP, lines[0].shape[1], 3), dtype=np.float32)
    return np.concatenate([part for line in lines for part in (line, gap)][:-1], axis=0)


def save(bpy, np, rgb, path):
    height, width = rgb.shape[:2]
    image = bpy.data.images.new(os.path.basename(path), width, height, alpha=False)
    rgba = np.ones((height, width, 4), dtype=np.float32)
    rgba[:, :, :3] = rgb
    image.pixels.foreach_set(rgba[::-1].ravel())
    image.filepath_raw = path
    image.file_format = "PNG"
    image.save()
    bpy.data.images.remove(image)


if __name__ == "__main__":
    argv = sys.argv[sys.argv.index("--") + 1:] if "--" in sys.argv else []
    try:
        main(argv)
    except Exception as error:  # Blender exits 0 after a traceback; every failure must exit non-zero
        message = str(error) if isinstance(error, SoloError) else f"{type(error).__name__}: {error}"
        print(f"light-solo: error: {message}", file=sys.stderr, flush=True)
        sys.exit(1)

"""Look kit: one call turns an arbitrary Blender scene into a lit, atmospheric shot.

    import look
    look.apply(bpy.context.scene, "rain-night", quality="preview", wetness=0.7)
    look.remove(bpy.context.scene)
    look.list_looks()

Every object/datablock the kit adds carries the custom property ``look_kit``; re-applying first removes the
previous look (idempotent). The user's objects are never deleted: their sun lamps may be hidden (restored by
remove), materials get a removable "LK Wet" node, practical emissions may be boosted (restored by remove).
"""
import time

import bpy

from . import layers, library, practicals, render
from .core import COLLECTION, SceneInfo, remove_layer_objects, save_state, state, tagged
from .looks import BASE, LAYERS, LOOKS, PARAMS, coerce, resolve

__all__ = ["apply", "remove", "list_looks", "PARAMS", "LOOKS", "LAYERS"]


def list_looks():
    return {
        "looks": {k: v[0] for k, v in LOOKS.items()},
        "layers": {k: v[0] for k, v in LAYERS.items()},
        "params": {k: {"default": v[0], "help": v[1]} for k, v in PARAMS.items()},
    }


def remove(scene, keep_settings=False):
    """Undo the kit: delete its objects, restore hidden suns, world, compositor, boosted emissions, wet nodes."""
    st = state(scene)
    remove_layer_objects()
    layers.remove_wet()
    for name in st.get("hidden", []):
        ob = bpy.data.objects.get(name)
        if ob is not None:
            ob.hide_render = False
    for key, val in st.get("world_strength", {}).items():
        wname, nname = key.split("|", 1)
        w = bpy.data.worlds.get(wname)
        if w is None:
            continue
        if nname == "<color>":
            w.color = val
        elif w.node_tree is not None and w.node_tree.nodes.get(nname) is not None:
            w.node_tree.nodes[nname].inputs["Strength"].default_value = val
    for mname in st.get("refraction", []):
        m = bpy.data.materials.get(mname)
        if m is not None:
            m.use_raytrace_refraction = False
    for mname, nodes in st.get("boosted", {}).items():
        m = bpy.data.materials.get(mname)
        if m is None or not m.use_nodes:
            continue
        for nname, val in nodes.items():
            n = m.node_tree.nodes.get(nname)
            if n is None:
                continue
            s = n.inputs.get("Emission Strength") if n.type == "BSDF_PRINCIPLED" else n.inputs.get("Strength")
            if s is not None:
                s.default_value = val
        if "look_kit_boosted" in m:
            del m["look_kit_boosted"]
    for mname, nodes in st.get("water_rough", {}).items():
        m = bpy.data.materials.get(mname)
        if m is None or not m.use_nodes:
            continue
        for nname, val in nodes.items():
            n = m.node_tree.nodes.get(nname)
            if n is not None and n.type == "BSDF_PRINCIPLED":
                n.inputs["Roughness"].default_value = val
    if not keep_settings:
        if "prev_world" in st:
            scene.world = bpy.data.worlds.get(st["prev_world"]) if st["prev_world"] else None
        if "prev_compositor" in st:
            scene.compositing_node_group = bpy.data.node_groups.get(st["prev_compositor"]) if st["prev_compositor"] else None
    for coll in (bpy.data.worlds, bpy.data.materials, bpy.data.node_groups, bpy.data.collections):
        for idb in [x for x in coll if tagged(x) and x.get("look_kit") not in ("library",)]:
            if keep_settings and idb.get("look_kit") in ("world", "camera"):
                continue
            if isinstance(idb, bpy.types.Collection) and idb.name == COLLECTION and idb.objects:
                continue
            coll.remove(idb)
    keep = {k: st[k] for k in ("prev_world", "prev_compositor") if keep_settings and k in st}
    save_state(scene, keep)
    for k in ("look_kit_look",) + (() if keep_settings else ("voyager_look",)):
        if k in scene:
            del scene[k]


def apply(scene, name, quality="preview", exposure_probe=True, **overrides):
    """Apply look/layer `name`; overrides are PARAMS keys (values or strings). Returns a JSON-able summary."""
    t0 = time.time()
    if name not in LOOKS and name not in LAYERS:
        raise ValueError(f"unknown look {name!r}; known: {', '.join(list(LOOKS) + list(LAYERS))}")
    if quality not in ("preview", "final"):
        raise ValueError("quality must be preview or final")
    p = resolve(name)
    for k, v in overrides.items():
        if k not in PARAMS:
            raise ValueError(f"unknown parameter {k!r}")
        p[k] = coerce(k, v) if isinstance(v, str) else v
    is_look = name in LOOKS
    # re-apply: a full look replaces everything the kit made; a layer replaces only its own kind
    if is_look:
        remove(scene, keep_settings=True)
    else:
        _remove_for_layer(scene, name)
    info = SceneInfo(scene)
    out = {"look": name, "quality": quality, "scene": info.summary()}
    if name == "godrays" and "fog" not in overrides:
        # on the scene's own sky: a bright world lights all the fog evenly and hides the shafts, so thin it
        wl = _world_luminance(scene)
        if wl > 0.05:
            # shafts need dark ambient: dim the scene's own sky (restored by remove) and let the sun carry the light
            out["world_dimmed_by"] = round(_dim_world(scene, 0.05 / wl), 3)
        out["world_luminance"] = round(wl, 3)
        if not info.indoor and not p["fog_visibility"]:
            # a deep outdoor shot looks through the whole fog box: thin it with depth so the far trees and the sky
            # don't turn into one grey wall; the shafts come from the sun's in-scatter, not from thick fog
            p["fog_visibility"] = max(info.subject_dist * 4.0, info.depth * 3.0, 8.0)
    if not info.indoor and info.depth > 300 and is_look:
        # a big outdoor set (valley, lake, city): the air scales with the set, not with the nearest object
        if not p["fog_visibility"] and p["fog_vis_depth"] > 0 and "fog_visibility" not in overrides:
            p["fog_visibility"] = info.depth * p["fog_vis_depth"]
        if p["fog_height_depth"] > 0 and "fog_height" not in overrides:
            p["fog_height"] = max(p["fog_height"], info.depth * p["fog_height_depth"])
        if p["vista_sun_prefer"] and p["sun_azimuth"] == "auto" and "sun_azimuth_prefer" not in overrides:
            # sun ahead of the camera, off to one side: sky gradient toward the sun, glowing haze, long shadows toward us
            p["sun_azimuth_prefer"] = p["vista_sun_prefer"]
            p["sun_azimuth_range"] = (max(p["vista_sun_prefer"] - 25.0, 10.0), p["vista_sun_prefer"] + 25.0)
        out["vista"] = {"fog_visibility": round(p["fog_visibility"], 1), "fog_height": round(p["fog_height"], 1)}
    if info.indoor and p["indoor_shafts"]:
        # a room: the sun comes in through the windows as shafts in dusty air
        p.update(sun_elevation=max(p["sun_elevation"], 18.0), sun_azimuth="auto", sun_azimuth_range=(100.0, 170.0),
                 precip_amount=p["precip_amount"],
                 sun_azimuth_prefer=140.0, fog=max(p["fog"], 0.12), fog_haze=0.3, fog_noise=0.2,
                 sky_strength=min(p["sky_strength"], 0.08),  # sky through the openings would light all the haze evenly
                 exposure_target=min(p["exposure_target"], 0.12), sun_strength=max(p["sun_strength"], 12.0),
                 fog_height=max(info.hi.z - info.ground_z, 3.0), godrays=False, sun_volume=4.0,
                 precip="dust" if p["precip"] == "none" else p["precip"])
        for k, v in overrides.items():
            p[k] = coerce(k, v) if isinstance(v, str) else v
        out["indoor_shafts"] = True
    if info.hero and p["bokeh_bulbs"] > 0 and p["dof"] < 0 and "dof" not in overrides:
        p["dof"] = 2.8  # a night product shot: shallow focus turns the background bulbs into bokeh
    if info.indoor and p["precip"] in ("rain", "snow") and "precip" not in overrides:
        # a room: the weather is outside; keep the interior dry
        p.update(precip="none", wetness=0.0 if "wetness" not in overrides else p["wetness"],
                 puddles=0.0 if "puddles" not in overrides else p["puddles"])
        out["indoor_dry"] = True
    if p["sun_strength"] > 0 or p["sky"] in ("day", "golden", "overcast", "blue-hour", "dawn"):
        layers.resolve_sun(scene, info, p)
        out["sun_azimuth"] = p["sun_azimuth"]
    if p["hide_user_suns"] or p["hide_user_lights"]:
        out["hidden_user_lights"] = layers.hide_user_suns(scene, p)
    if p["sky"] != "keep":
        out.update(layers.world(scene, info, p))
    out.update(layers.sun(scene, info, p))
    out.update(layers.studio(scene, info, p))
    out.update(layers.hero_light(scene, info, p))
    out.update(practicals.practicals(scene, info, p))
    out.update(layers.fog(scene, info, p))
    out.update(layers.godrays(scene, info, p))
    out.update(layers.precip(scene, info, p))
    out.update(layers.calm_water(scene, info, p))  # before wet: the wet node keeps the roughness it finds
    out.update(layers.wet(scene, info, p))
    out.update(layers.droplets(scene, info, p))
    if is_look or name == "camera":
        out.update(render.engine(scene, info, p, quality))
        out["glass_refraction_fixed"] = render.glass_fix(scene, info)
        render.color(scene, p)
        out.update(render.camera(scene, info, p))
    else:
        scene.eevee.use_volumetric_shadows = True
        scene.eevee.volumetric_end = max(scene.eevee.volumetric_end, info.depth * 2.0)
    scene["look_kit_look"] = name
    _write_voyager_look(scene, name, p, is_look)
    out["setup_s"] = round(time.time() - t0, 2)
    if p["exposure"] == "auto" and exposure_probe:
        hero_box = info.subject_box if info.hero and p["hero_exposure"] > 0 else None
        ev, secs, key = render.auto_exposure(scene, p["exposure_target"], hero_box, p["hero_exposure"],
                                             p["exposure_ceiling"], p["exposure_floor"],
                                             getattr(info, "subject_box", None))
        out["exposure"] = round(ev, 2)
        out["exposure_probe_s"] = round(secs, 2)
        out["exposure_probe"] = dict(render.PROBE)
    elif isinstance(p["exposure"], (int, float)):
        out["exposure"] = p["exposure"]
    return out


def _dim_world(scene, k):
    st = state(scene)
    w = scene.world
    saved = st.setdefault("world_strength", {})
    if w.use_nodes and w.node_tree is not None:
        for n in w.node_tree.nodes:
            if n.type == "BACKGROUND" and not n.inputs["Strength"].is_linked:
                key = w.name + "|" + n.name
                saved.setdefault(key, n.inputs["Strength"].default_value)
                n.inputs["Strength"].default_value = saved[key] * k
    else:
        saved.setdefault(w.name + "|<color>", list(w.color))
        w.color = [c * k for c in saved[w.name + "|<color>"]]
    save_state(scene, st)
    return k


def _world_luminance(scene):
    """Rough brightness of the world: Background colour x strength (sky textures count as bright daylight)."""
    w = scene.world
    if w is None:
        return 0.0
    if not w.use_nodes or w.node_tree is None:
        c = w.color
        return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
    tot = 0.0
    for n in w.node_tree.nodes:
        if n.type != "BACKGROUND":
            continue
        col, st = n.inputs["Color"], n.inputs["Strength"]
        strength = st.default_value if not st.is_linked else 1.0
        if col.is_linked:
            tot += 0.5 * strength  # an HDRI or sky: assume daylight
        else:
            c = col.default_value
            tot += (0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]) * strength
    return tot


def _write_voyager_look(scene, name, p, is_look):
    """scene['voyager_look'] (JSON string) tells render-final.py which engine and settings the look wants for
    finals. A layer merges into the existing record instead of replacing it."""
    import json
    try:
        rec = json.loads(scene.get("voyager_look", "{}")) if isinstance(scene.get("voyager_look", "{}"), str) else dict(scene["voyager_look"])
    except (ValueError, TypeError):
        rec = {}
    if is_look or "name" not in rec:
        fe = p["final_engine"] if p["engine"] == "auto" else p["engine"]
        rec = {"name": name, "final_engine": fe, "layers": [],
               "final": {"cycles_samples": p["cycles_samples"], "adaptive_threshold": 0.02, "denoise": True,
                         "eevee_samples": 128, "volumetric_tile_size": 4, "motion_blur": p["motion_blur"]},
               "apply_final": "look.py --look %s --quality final" % name}
        if not is_look:
            rec["layers"] = [name]
    elif name not in rec.setdefault("layers", []):
        rec["layers"].append(name)
    if is_look:
        rec["layers"] = rec.get("layers", [])
    scene["voyager_look"] = json.dumps(rec)


def _remove_for_layer(scene, name):
    kinds = {"fog": ["fog"], "godrays": ["godrays", "sun", "fog"], "rain": ["precip"], "snow": ["precip"], "dust": ["precip"],
             "wet": [], "practicals": ["practicals"], "camera": []}[name]
    for k in kinds:
        remove_layer_objects(k)
    if name in ("wet", "rain"):
        layers.remove_wet()

"""Shared state for the look kit: tagging what the kit adds, remembering what it changes, and reading an
unknown scene (camera, ground, subject, bounds) without touching the user's objects."""
import json
import math
import re

import bpy
from mathutils import Vector

SET_NAMES = re.compile(r"backdrop|background|\bbg\b|floor|ground|wall|sweep|cyc|seamless|plane|terrain|road|street|"
                       r"sidewalk|table|desk|counter|surface|stage|ceiling|sky|pedestal|plinth|podium|turntable|riser|"
                       r"lake|\bsea\b|ocean|pond|shore|landscape", re.I)
GROUND_NAMES = re.compile(r"backdrop|floor|ground|sweep|cyc|seamless|plane|surface|table|desk|counter|stage|road|"
                          r"lake|\bsea\b|ocean|pond|shore|terrain|landscape", re.I)
TAG = "look_kit"  # custom property on every datablock the kit creates; value = the layer that made it
STATE = "look_kit_state"  # scene property: JSON of what the kit changed on user data, for re-apply/remove
COLLECTION = "Look Kit"


def tag(idblock, layer):
    idblock[TAG] = layer
    return idblock


def tagged(idblock, layer=None):
    v = idblock.get(TAG)
    return v is not None and (layer is None or v == layer)


def state(scene):
    try:
        return json.loads(scene.get(STATE, "{}"))
    except ValueError:
        return {}


def save_state(scene, st):
    scene[STATE] = json.dumps(st)


def kit_collection(scene):
    col = bpy.data.collections.get(COLLECTION)
    if col is None:
        col = tag(bpy.data.collections.new(COLLECTION), "core")
    if col.name not in scene.collection.children:
        scene.collection.children.link(col)
    return col


def new_object(scene, name, data, layer):
    ob = tag(bpy.data.objects.new(name, data), layer)
    if data is not None and hasattr(data, "keys"):
        tag(data, layer)
    kit_collection(scene).objects.link(ob)
    return ob


def remove_layer_objects(layer=None):
    """Delete objects (and their now-unused data) the kit created; user objects are never touched."""
    for ob in [o for o in bpy.data.objects if tagged(o, layer)]:
        data = ob.data
        bpy.data.objects.remove(ob, do_unlink=True)
        if data is None or data.users:
            continue
        for coll in (bpy.data.meshes, bpy.data.lights, bpy.data.cameras, bpy.data.curves):
            if coll.get(data.name) == data:
                coll.remove(data)
                break


def user_objects(scene):
    return [o for o in scene.objects if not tagged(o)]


# ---------- reading an unknown scene ----------

def world_bbox(ob):
    pts = [ob.matrix_world @ Vector(c) for c in ob.bound_box]
    lo = Vector((min(p.x for p in pts), min(p.y for p in pts), min(p.z for p in pts)))
    hi = Vector((max(p.x for p in pts), max(p.y for p in pts), max(p.z for p in pts)))
    return lo, hi


def _emissive_strength(mat):
    """Brightest emission a material shows (Principled Emission or Emission shader), 0 if none."""
    if mat is None or not mat.use_nodes or mat.node_tree is None:
        return 0.0, (1.0, 1.0, 1.0)
    best, col = 0.0, (1.0, 1.0, 1.0)
    for n in mat.node_tree.nodes:
        if n.type == "BSDF_PRINCIPLED":
            s = n.inputs["Emission Strength"]
            c = n.inputs["Emission Color"]
            strength = s.default_value if not s.is_linked else 1.0
            colv = tuple(c.default_value[:3]) if not c.is_linked else (1.0, 0.9, 0.7)
            if c.is_linked and not s.is_linked and strength > 0:
                lum = 1.0
            else:
                lum = max(colv)
            if strength * lum > best:
                best, col = strength * lum, colv
        elif n.type == "EMISSION":
            s = n.inputs["Strength"]
            c = n.inputs["Color"]
            strength = s.default_value if not s.is_linked else 1.0
            colv = tuple(c.default_value[:3]) if not c.is_linked else (1.0, 0.9, 0.7)
            if strength * max(colv) > best:
                best, col = strength * max(colv), colv
    return best, col


def emissive_info(ob):
    best, col = 0.0, (1, 1, 1)
    for slot in getattr(ob, "material_slots", []):
        s, c = _emissive_strength(slot.material)
        if s > best:
            best, col = s, c
    return best, col


def volume_only(ob):
    """A mesh that is only a volume container (mist, clouds, haze boxes): no surface to light, land on or hide behind."""
    mats = [sl.material for sl in getattr(ob, "material_slots", []) if sl.material is not None]
    if not mats:
        return False
    for m in mats:
        if not m.use_nodes or m.node_tree is None:
            return False
        outs = [n for n in m.node_tree.nodes if n.type == "OUTPUT_MATERIAL"]
        if not outs or any(n.inputs["Surface"].is_linked for n in outs) or not any(n.inputs["Volume"].is_linked for n in outs):
            return False
    return True


def _passable(ob):
    ob = ob.original if hasattr(ob, "original") else ob
    return tagged(ob) or volume_only(ob)


class SceneInfo:
    """What the kit needs to know about a scene it has never seen."""

    def __init__(self, scene):
        self.scene = scene
        self.camera = scene.camera
        meshes = [o for o in user_objects(scene) if o.type in {"MESH", "CURVE", "SURFACE", "META", "FONT"}
                  and not o.hide_render and not volume_only(o)]
        if len(meshes) > 2:
            # scatter/instance sources parked far below the set (e.g. z = -10000) are not part of the scene's extent
            boxes = [world_bbox(o) for o in meshes]
            foot = [max(b[1].x - b[0].x, b[1].y - b[0].y) for b in boxes]
            k = foot.index(max(foot))
            floor_z = boxes[k][0].z - max(100.0, 0.05 * foot[k])
            meshes = [o for o, b in zip(meshes, boxes) if b[1].z >= floor_z]
        self.meshes = meshes
        if meshes:
            boxes = [world_bbox(o) for o in meshes]
            self.lo = Vector((min(b[0].x for b in boxes), min(b[0].y for b in boxes), min(b[0].z for b in boxes)))
            self.hi = Vector((max(b[1].x for b in boxes), max(b[1].y for b in boxes), max(b[1].z for b in boxes)))
        else:
            self.lo, self.hi = Vector((-5, -5, 0)), Vector((5, 5, 3))
        if self.camera is None:
            self.camera = self._make_camera()
        self.cam_loc = self.camera.matrix_world.translation.copy()
        self.cam_fwd = (self.camera.matrix_world.to_quaternion() @ Vector((0, 0, -1))).normalized()
        self.ground = self._find_ground()
        self.ground_z = self._ground_z()
        self.subject = self._find_subject()
        if self.subject is not None:
            lo, hi = world_bbox(self.subject)
            self.subject_center = (lo + hi) / 2
            self.subject_size = max((hi - lo).length, 1e-3)
        else:
            self.subject_center = self.cam_loc + self.cam_fwd * 5
            self.subject_size = 1.0
        self.subject_dist = max((self.subject_center - self.cam_loc).dot(self.cam_fwd), 0.05)
        # how far the shot reaches: from the camera to the far side of what's in front of it
        self.depth = max(self.subject_dist * 2.0, self._view_depth())
        self.size = max((self.hi - self.lo).length, self.subject_size)
        self.focus_dist = self._focus()
        # a product-scale hero (not a building or a landscape): looks keep it lit and expose for it
        self.subject_box = self._projected_box(self.subject) if self.subject is not None else None
        self.hero = self.subject is not None and self.subject_size < 3.0 and self.subject_box is not None
        self.emissive = [(o,) + emissive_info(o) for o in meshes]
        self.emissive = [(o, s, c) for o, s, c in self.emissive if s > 0.05]
        self.indoor = self._is_indoor()

    def _make_camera(self):
        cam = bpy.data.cameras.new("Look Kit Camera")
        ob = new_object(self.scene, "Look Kit Camera", cam, "camera")
        c = (self.lo + self.hi) / 2
        r = max((self.hi - self.lo).length, 1.0)
        ob.location = c + Vector((0, -r * 1.1, r * 0.35))
        ob.rotation_euler = (c - ob.location).to_track_quat("-Z", "Y").to_euler()
        self.scene.camera = ob
        return ob

    def _find_ground(self):
        span = max(self.hi.x - self.lo.x, self.hi.y - self.lo.y, 1e-3)
        out = []
        for o in self.meshes:
            lo, hi = world_bbox(o)
            w = max(hi.x - lo.x, hi.y - lo.y)
            h = hi.z - lo.z
            rng = max(self.hi.z - self.lo.z, 1e-3)
            flat = w > 0.25 * span and h < 0.08 * w
            # a flat sheet (water, a shore) counts by its top: hills displaced below it must not push it out
            low = lo.z < self.lo.z + 0.15 * rng + 0.05 or (flat and hi.z < self.lo.z + 0.25 * rng + 0.05)
            if low and (flat or GROUND_NAMES.search(o.name)):
                out.append(o)
        return out

    def _ground_z(self):
        if self.ground:
            return max(world_bbox(o)[1].z for o in self.ground) if len(self.ground) == 1 else min(
                world_bbox(o)[1].z for o in self.ground)
        return self.lo.z

    def _projected(self, ob):
        from bpy_extras.object_utils import world_to_camera_view
        pts = [world_to_camera_view(self.scene, self.camera, ob.matrix_world @ Vector(c)) for c in ob.bound_box]
        if all(p.z <= 0 for p in pts):
            return 0.0, 1.0
        xs = [min(max(p.x, 0), 1) for p in pts if p.z > 0]
        ys = [min(max(p.y, 0), 1) for p in pts if p.z > 0]
        if not xs:
            return 0.0, 1.0
        area = (max(xs) - min(xs)) * (max(ys) - min(ys))
        cx, cy = (max(xs) + min(xs)) / 2, (max(ys) + min(ys)) / 2
        return area, math.hypot(cx - 0.5, cy - 0.5)

    def _projected_box(self, ob):
        from bpy_extras.object_utils import world_to_camera_view
        pts = [world_to_camera_view(self.scene, self.camera, ob.matrix_world @ Vector(c)) for c in ob.bound_box]
        pts = [p for p in pts if p.z > 0]
        if not pts:
            return None
        x0, x1 = max(min(p.x for p in pts), 0.0), min(max(p.x for p in pts), 1.0)
        y0, y1 = max(min(p.y for p in pts), 0.0), min(max(p.y for p in pts), 1.0)
        return (x0, y0, x1, y1) if x1 > x0 and y1 > y0 else None

    def _find_subject(self):
        best, score = None, 0.0
        named_set = [o for o in self.meshes if SET_NAMES.search(o.name)]
        props = [o for o in self.meshes if o not in self.ground and o not in named_set]
        for o in props or [o for o in self.meshes if o not in self.ground]:
            area, off = self._projected(o)
            if area <= 0 or area > 0.98:  # a wall/backdrop filling the frame is not the subject
                continue
            s = area * (1.2 - min(off, 0.7))
            if s > score:
                best, score = o, s
        return best

    def _view_depth(self):
        far = 0.0
        for o in self.meshes:
            area, _ = self._projected(o)
            if area <= 0:
                continue
            lo, hi = world_bbox(o)
            for p in (lo, hi):
                far = max(far, (p - self.cam_loc).dot(self.cam_fwd))
        return far if far > 0 else 20.0

    def _focus(self):
        """Focus on the subject's surface nearest the frame centre: rays through a small cross at the centre of
        frame; a hit on the subject (or, failing that, on anything but the ground) wins; else subject distance."""
        dg = bpy.context.evaluated_depsgraph_get()
        cam = self.camera
        frame = [cam.matrix_world @ v for v in cam.data.view_frame(scene=self.scene)]
        centre = sum(frame, Vector()) / 4
        right = (frame[0] - frame[3]) / 2
        up = (frame[0] - frame[1]) / 2
        best = None
        for dx, dy in ((0, 0), (0.15, 0), (-0.15, 0), (0, 0.15), (0, -0.15), (0, -0.3), (0.3, 0), (-0.3, 0)):
            t = centre + right * dx + up * dy
            ok, loc, ob = self._cast(dg, self.cam_loc, (t - self.cam_loc).normalized(), 1e5)
            if not ok:
                continue
            d = (loc - self.cam_loc).dot(self.cam_fwd)
            if self.subject is not None and ob == self.subject:
                return d
            if best is None and ob not in self.ground and not tagged(ob):
                best = d
        return best if best is not None else self.subject_dist

    def _is_indoor(self):
        """A ceiling over the camera: cast a few rays upward and count hits on user geometry."""
        dg = bpy.context.evaluated_depsgraph_get()
        hits = 0
        for d in (Vector((0, 0, 1)), Vector((0.3, 0, 1)), Vector((-0.3, 0, 1)), Vector((0, 0.3, 1)), Vector((0, -0.3, 1))):
            ok, _loc, _ob = self._cast(dg, self.cam_loc, d.normalized(), 60)
            hits += 1 if ok else 0
        return hits >= 4

    def _cast(self, dg, o, d, dist):
        """Ray cast that passes through the kit's own objects and volume-only boxes (mist, clouds)."""
        start = o
        for _ in range(8):
            ok, loc, _n, _i, ob, _m = self.scene.ray_cast(dg, o, d, distance=dist - (o - start).length)
            if not ok:
                return False, None, None
            if not _passable(ob):
                return True, loc, (ob.original if hasattr(ob, "original") else ob)
            o = loc + d * 0.01
        return False, None, None

    def summary(self):
        return {
            "camera": self.camera.name,
            "subject": self.subject.name if self.subject else None,
            "ground": [o.name for o in self.ground],
            "ground_z": round(self.ground_z, 3),
            "subject_distance_m": round(self.subject_dist, 2),
            "shot_depth_m": round(self.depth, 1),
            "practicals_found": len(self.emissive),
            "indoor": self.indoor,
            "hero": self.hero,
        }

"""Small helpers for building node trees by name (Blender 5.x nodes have several same-named sockets, one per
data type; only the available one is wanted)."""


def sock(node, name, out=False):
    socks = node.outputs if out else node.inputs
    for s in socks:
        if s.name == name and s.enabled and not getattr(s, "is_unavailable", False):
            return s
    if isinstance(name, int):
        return socks[name]
    raise KeyError(f"{node.bl_idname} has no available {'output' if out else 'input'} {name!r}")


class Tree:
    def __init__(self, tree):
        self.t = tree
        self.n = tree.nodes
        self.l = tree.links

    def node(self, typ, x=0, y=0, **props):
        n = self.n.new(typ)
        n.location = (x, y)
        for k, v in props.items():
            if k.startswith("in_"):
                continue
            setattr(n, k, v)
        for k, v in props.items():
            if k.startswith("in_"):
                sock(n, k[3:].replace("_", " ")).default_value = v
        return n

    def set(self, node, **inputs):
        for k, v in inputs.items():
            sock(node, k.replace("_", " ")).default_value = v
        return node

    def link(self, a, a_out, b, b_in):
        """a_out/b_in: socket name or index; a may also be a socket."""
        src = a if not hasattr(a, "outputs") else (a.outputs[a_out] if isinstance(a_out, int) else sock(a, a_out, True))
        dst = b.inputs[b_in] if isinstance(b_in, int) else sock(b, b_in)
        return self.l.new(src, dst)

    def math(self, op, a=None, b=None, x=0, y=0, clamp=False):
        n = self.node("ShaderNodeMath", x, y, operation=op, use_clamp=clamp)
        for i, v in enumerate((a, b)):
            if v is None:
                continue
            if isinstance(v, (int, float)):
                n.inputs[i].default_value = v
            else:
                self.l.new(v, n.inputs[i])
        return n.outputs[0]

    def vmath(self, op, a=None, b=None, x=0, y=0, scale=None):
        n = self.node("ShaderNodeVectorMath", x, y, operation=op)
        for i, v in enumerate((a, b)):
            if v is None:
                continue
            if isinstance(v, (tuple, list)):
                n.inputs[i].default_value = v
            else:
                self.l.new(v, n.inputs[i])
        if scale is not None:
            if isinstance(scale, (int, float)):
                sock(n, "Scale").default_value = scale
            else:
                self.l.new(scale, sock(n, "Scale"))
        return n.outputs["Value"] if op in {"DOT_PRODUCT", "LENGTH", "DISTANCE"} else n.outputs["Vector"]

    def mix(self, data_type, fac, a, b, x=0, y=0, blend="MIX", clamp=True):
        n = self.node("ShaderNodeMix", x, y, data_type=data_type)
        if data_type == "RGBA":
            n.blend_type = blend
            n.clamp_result = False
        n.clamp_factor = clamp
        fs = sock(n, "Factor")
        if isinstance(fac, (int, float)):
            fs.default_value = fac
        else:
            self.l.new(fac, fs)
        ins = [s for s in n.inputs if s.enabled and s.name in ("A", "B")]
        for s, v in zip(ins, (a, b)):
            if isinstance(v, (int, float, tuple, list)):
                s.default_value = v
            else:
                self.l.new(v, s)
        return sock(n, "Result", True)

    def map_range(self, v, fmin, fmax, tmin=0.0, tmax=1.0, x=0, y=0, interp="LINEAR"):
        n = self.node("ShaderNodeMapRange", x, y, interpolation_type=interp)
        vals = {"From Min": fmin, "From Max": fmax, "To Min": tmin, "To Max": tmax}
        if isinstance(v, (int, float)):
            sock(n, "Value").default_value = v
        else:
            self.l.new(v, sock(n, "Value"))
        for k, val in vals.items():
            s = sock(n, k)
            if isinstance(val, (int, float)):
                s.default_value = val
            else:
                self.l.new(val, s)
        return sock(n, "Result", True)


def group_io(ng, inputs=(), outputs=()):
    """inputs/outputs: (name, socket_type, default, min, max)."""
    for spec in inputs:
        name, typ, *rest = spec
        s = ng.interface.new_socket(name, in_out="INPUT", socket_type=typ)
        if rest and rest[0] is not None and hasattr(s, "default_value"):
            s.default_value = rest[0]
        if len(rest) > 2 and hasattr(s, "min_value"):
            s.min_value, s.max_value = rest[1], rest[2]
    for name, typ in outputs:
        ng.interface.new_socket(name, in_out="OUTPUT", socket_type=typ)

"""Offline control filtering and shape-preserving authored paths (Blender Python)."""

import math
import bpy
from mathutils import Quaternion, Vector


def smooth_controls(rig, scene, frames, settings):
    """Filter a snapshot so writing keys cannot contaminate later samples.

    A symmetric time window avoids a causal filter's delay. Root paths and contact
    constraints are applied separately, after filtering, to preserve their anchors.
    """
    names = ["torso"] + [
        name + "." + side
        for side in ("L", "R")
        for name in ("hand_ik", "foot_ik", "upper_arm_ik_target", "thigh_ik_target")
    ]
    samples = {name: {"location": [], "rotation_quaternion": []} for name in names}
    for f in frames:
        frame = 1 + f["seconds"] * 30
        scene.frame_set(math.floor(frame), subframe=frame % 1)
        for name in names:
            bone = rig.pose.bones[name]
            for channel in samples[name]:
                samples[name][channel].append(getattr(bone, channel).copy())
    times = [f["seconds"] for f in frames]
    for name in names:
        sigma = (
            settings.get("pole_sigma_seconds", 0.12)
            if "target" in name
            else settings.get("sigma_seconds", 0.08)
        )
        for channel, values in samples[name].items():
            filtered = gaussian(values, times, sigma, channel == "rotation_quaternion")
            bone = rig.pose.bones[name]
            for t, value in zip(times, filtered):
                setattr(bone, channel, value)
                bone.keyframe_insert(channel, frame=1 + t * 30, group="Filtered " + name)


def gaussian(values, times, sigma, rotations=False):
    if rotations:
        aligned = [values[0].copy()]
        for value in values[1:]:
            value = value.copy()
            if aligned[-1].dot(value) < 0:
                value.negate()
            aligned.append(value)
        values = aligned
    result = []
    for index, time in enumerate(times):
        weights = [
            (i, math.exp(-0.5 * ((t - time) / sigma) ** 2))
            for i, t in enumerate(times)
            if abs(t - time) <= 3 * sigma
        ]
        total = sum(weight for _, weight in weights)
        value = [0.0] * len(values[index])
        for i, weight in weights:
            for axis in range(len(value)):
                value[axis] += values[i][axis] * weight / total
        result.append(Quaternion(value).normalized() if rotations else Vector(value))
    return result


def interpolate(keys, time):
    """Monotone cubic Hermite interpolation; held coordinates stay held.

    Harmonic-mean slopes prevent overshoot below the floor and carry velocity
    through swing midpoints. Start/end slopes are zero for these authored paths.
    """
    index = next(
        (i for i, (a, b) in enumerate(zip(keys, keys[1:])) if a["time"] <= time <= b["time"]), None
    )
    if index is None:
        raise ValueError("Time outside authored keys")
    a, b = keys[index : index + 2]
    span = b["time"] - a["time"]
    u = (time - a["time"]) / span
    result = []
    for axis in range(len(a["position"])):
        slopes = []
        for k in (index, index + 1):
            if k == 0 or k == len(keys) - 1:
                slopes.append(0)
                continue
            before, current, after = keys[k - 1 : k + 2]
            left = current["time"] - before["time"]
            right = after["time"] - current["time"]
            d0 = (current["position"][axis] - before["position"][axis]) / left
            d1 = (after["position"][axis] - current["position"][axis]) / right
            slopes.append(
                0
                if d0 * d1 <= 0
                else 3 * (left + right) / ((2 * right + left) / d0 + (right + 2 * left) / d1)
            )
        result.append(
            (2 * u**3 - 3 * u**2 + 1) * a["position"][axis]
            + (u**3 - 2 * u**2 + u) * span * slopes[0]
            + (-2 * u**3 + 3 * u**2) * b["position"][axis]
            + (u**3 - u**2) * span * slopes[1]
        )
    return Vector(result)


def stabilize_poles(rig, scene, overrides, max_degrees_per_second=240):
    """Keep each IK bend guide on a continuous side of its limb axis.

    Near-straight limbs do not determine a stable bend plane. Transport the previous
    plane through that ambiguity instead of accepting a one-frame 180-degree flip.
    """
    names = [
        (upper + "_ik_target." + side, "ORG-" + upper + "." + side, end + "_ik." + side)
        for side in ("L", "R")
        for upper, end in (("upper_arm", "hand"), ("thigh", "foot"))
    ]
    samples = {name: [] for name, _, _ in names}
    for frame in range(1, scene.frame_end + 1):
        scene.frame_set(frame)
        for name, upper, end in names:
            samples[name].append(
                (
                    rig.pose.bones[upper].head.copy(),
                    rig.pose.bones[end].matrix.translation.copy(),
                    rig.pose.bones[name].matrix.translation.copy(),
                )
            )
    paths = {rig.pose.bones[name].path_from_id("location") for name, _, _ in names}
    for layer in rig.animation_data.action.layers:
        for strip in layer.strips:
            for bag in strip.channelbags:
                for curve in list(bag.fcurves):
                    if curve.data_path in paths:
                        bag.fcurves.remove(curve)
    adjustments = {
        "hemisphere_corrections": 0,
        "rate_limited_samples": 0,
        "authored_knee_samples": 0,
    }
    for name, _, _ in names:
        previous = None
        bone = rig.pose.bones[name]
        for frame, (start, end, pole) in enumerate(samples[name], 1):
            axis = (end - start).normalized()
            candidate = pole - start - axis * (pole - start).dot(axis)
            if name.startswith("thigh") and any(
                o["bone"] == "foot_ik." + name[-1]
                and o["keys"][0]["time"] <= (frame - 1) / 30 <= o["keys"][-1]["time"]
                for o in overrides
            ):
                forward = Vector((0, -1, 0))
                candidate = forward - axis * forward.dot(axis)
                adjustments["authored_knee_samples"] += 1
            transported = (
                previous - axis * previous.dot(axis) if previous is not None else candidate
            )
            if candidate.length < 0.02:
                candidate = transported
            if candidate.length < 1e-5 or transported.length < 1e-5:
                raise ValueError("Degenerate IK guide; author a bend direction")
            candidate.normalize()
            transported.normalize()
            if candidate.dot(transported) < 0:
                candidate.negate()
                adjustments["hemisphere_corrections"] += 1
            angle = transported.angle(candidate)
            limit = math.radians(max_degrees_per_second / 30)
            if angle > limit:
                candidate = transported.slerp(candidate, limit / angle)
                adjustments["rate_limited_samples"] += 1
            previous = candidate.copy()
            scene.frame_set(frame)
            matrix = bone.matrix.copy()
            matrix.translation = (start + end) / 2 + candidate * 0.6
            bone.matrix = matrix
            bpy.context.view_layer.update()
            bone.keyframe_insert("location", frame=frame, group="Stable IK " + name)
    return adjustments


def repair_gaps(frames, max_seconds):
    """Interpolate only bounded whole-pose gaps; never modify source records."""
    repaired = []
    result = []
    for index, frame in enumerate(frames):
        if frame["world"] is not None:
            result.append(frame)
            continue
        before = next((f for f in reversed(frames[:index]) if f["world"] is not None), None)
        after = next((f for f in frames[index + 1 :] if f["world"] is not None), None)
        if before is None or after is None or after["seconds"] - before["seconds"] > max_seconds:
            raise ValueError("Unbounded or long whole-pose tracking gap; trim or re-record")
        weight = (frame["seconds"] - before["seconds"]) / (after["seconds"] - before["seconds"])
        world = [
            [a[i] + (b[i] - a[i]) * weight for i in range(3)] + [min(a[i], b[i]) for i in (3, 4)]
            for a, b in zip(before["world"], after["world"])
        ]
        result.append({**frame, "world": world})
        repaired.append(frame["seconds"])
    return result, repaired


def motion_metrics(samples):
    result = {}
    for name, values in samples.items():
        angles = [
            math.degrees(2 * math.acos(min(1, abs(a[1].dot(b[1])))))
            for a, b in zip(values, values[1:])
        ]
        acceleration = [
            ((c[0] - b[0]) - (b[0] - a[0])).length * 900
            for a, b, c in zip(values, values[1:], values[2:])
        ]
        result[name] = {
            "max_degrees_per_frame": max(angles, default=0),
            "p95_degrees_per_frame": sorted(angles)[int(len(angles) * 0.95)] if angles else 0,
            "rms_acceleration_m_s2": math.sqrt(sum(a * a for a in acceleration) / len(acceleration))
            if acceleration
            else 0,
        }
    return result

"""Helpers for render-final.py: routing, planning, and the work it runs inside Blender
(inspect, pack, probe, render, upscale and review) through its --worker option.

render-final.py copies this file next to itself on a Voyager GPU machine; it is not a command.
"""

import hashlib
import importlib.util
import json
import math
import os
import runpy
import subprocess
import time
import sys
from pathlib import Path


def read(path):
    try:
        return json.loads(Path(path).read_text())
    except (OSError, ValueError, TypeError):
        return {}


def write(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2) + "\n")
    temporary.replace(path)


def digest(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as source:
        for data in iter(lambda: source.read(1024 * 1024), b""):
            h.update(data)
    return h.hexdigest()


def preference():
    home = os.environ.get("VOYAGER_HOME")
    if not home:
        if sys.platform == "darwin":
            home = str(Path.home() / "Library/Application Support/Voyager")
        elif sys.platform == "win32":
            home = str(Path(os.environ.get("LOCALAPPDATA", Path.home())) / "Voyager")
        else:
            home = str(
                Path(os.environ.get("XDG_DATA_HOME", Path.home() / ".local/share"))
                / "voyager"
            )
    settings = os.environ.get("VOYAGER_GPU_SETTINGS_PATH")
    if not settings:
        settings = (
            read(Path(home) / "voyager-server.json")
            .get("telemetry", {})
            .get("settingsPath")
        )
    value = read(settings).get("voyagerGpuUsage", "ask")
    return value if value in ("always", "ask", "never") else "ask"


def route(where, usage, connected, estimate):
    if where == "machine":
        if usage == "never":
            raise RuntimeError(
                "Voyager GPUs are set to Never; choose --where local or change Settings"
            )
        if not connected:
            raise RuntimeError("Voyager is signed out; choose --where local or sign in")
        return "machine"
    if where == "local" or usage == "never" or not connected or estimate <= 180:
        return "local"
    return "machine" if usage == "always" else "ask"


def run(argv, log=None, timeout=None):
    if log:
        with Path(log).open("a") as stream:
            result = subprocess.run(
                [str(x) for x in argv],
                stdout=stream,
                stderr=stream,
                check=False,
                timeout=timeout,
            )
    else:
        result = subprocess.run(
            [str(x) for x in argv], stdout=sys.stderr, stderr=sys.stderr, check=False
        )
    if result.returncode:
        raise RuntimeError(
            f"{Path(str(argv[0])).name} failed ({result.returncode}); see {log or 'stderr'}"
        )


def cli_json(cli, *args):
    result = subprocess.run(
        [*cli, *args], capture_output=True, text=True, timeout=120, check=False
    )
    data = json.loads(result.stdout)
    if result.returncode or data.get("ok") is False or data.get("error"):
        raise RuntimeError(
            "Voyager command failed: " + str(data.get("error", result.stderr))[:300]
        )
    return data.get("result", data)


def blender_worker(a):
    import bpy

    if a.worker == "upscale":
        job = read(a.result)
        for source, target in job["pairs"]:
            image = bpy.data.images.load(source)
            image.scale(*job["size"])
            image.filepath_raw = target
            image.file_format = "PNG"
            image.save()
            bpy.data.images.remove(image)
        return
    if a.worker == "review":
        import numpy

        job = read(a.result)

        def load(source, width):
            image = bpy.data.images.load(source)
            image.scale(width, round(width * image.size[1] / image.size[0]))
            pixels = numpy.empty(image.size[0] * image.size[1] * 4, numpy.float32)
            image.pixels.foreach_get(pixels)
            shape = (image.size[1], image.size[0], 4)
            bpy.data.images.remove(image)
            return pixels.reshape(shape)

        def luma(pixels):
            return pixels[..., :3] @ numpy.array([0.2126, 0.7152, 0.0722], numpy.float32)

        tiles = [load(source, 640) for source in job["sheet"]]
        # Blender rows run bottom-up: the first frame goes top left.
        grid = numpy.concatenate(
            [numpy.concatenate(tiles[2:4], 1), numpy.concatenate(tiles[0:2], 1)], 0
        )
        sheet = bpy.data.images.new("review", grid.shape[1], grid.shape[0], alpha=True)
        sheet.pixels.foreach_set(grid.ravel())
        sheet.filepath_raw = job["out"]
        sheet.file_format = "PNG"
        sheet.save()
        lumas = [luma(load(source, 320)) for source in job["samples"]]
        means = [float(y.mean()) for y in lumas]
        measured = {
            "mean_luminance": round(float(numpy.mean(means)), 3),
            "clipped_percent": round(
                100 * float(numpy.mean([(y > 0.98).mean() for y in lumas])), 2
            ),
            "contrast": round(float(numpy.mean([y.std() for y in lumas])), 3),
            # Mean change between sampled frames across the shot, and between neighbours.
            "motion": round(
                float(numpy.median([abs(p - q).mean() for p, q in zip(lumas, lumas[1:])]))
                if len(lumas) > 1
                else 0.0,
                4,
            ),
            "flicker": round(
                max(
                    (
                        abs(float(luma(load(p, 320)).mean()) - float(luma(load(q, 320)).mean()))
                        for p, q in job["pairs"]
                    ),
                    default=0.0,
                ),
                4,
            ),
        }
        problems = []
        if measured["mean_luminance"] < 0.08:
            problems.append(f"too dark: mean luminance {measured['mean_luminance']}")
        if measured["mean_luminance"] > 0.7:
            problems.append(f"washed out: mean luminance {measured['mean_luminance']}")
        if measured["clipped_percent"] > 3:
            problems.append(f"clipped: {measured['clipped_percent']}% of pixels are white")
        if measured["contrast"] < 0.06:
            problems.append(f"flat: luminance spread {measured['contrast']}")
        if len(job["samples"]) > 1 and measured["motion"] < 0.004:
            problems.append("static: the sampled frames barely change across the shot")
        if measured["flicker"] > 0.02:
            problems.append(
                f"flicker: neighbouring frames differ in brightness by {measured['flicker']}"
            )
        write(job["result"], {"measured": measured, "problems": problems})
        return
    scene = bpy.context.scene
    spec = importlib.util.spec_from_file_location("final_renderer", a.helper)
    renderer = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(renderer)
    if a.worker == "inspect":
        tag = scene.get("voyager_look", {})
        if isinstance(tag, str):
            try:
                tag = json.loads(tag)
            except ValueError:
                tag = {}
        tagged = str(tag.get("final_engine", "")).lower() if hasattr(tag, "get") else ""
        # Linked volume outputs are a useful conservative GI cue. A saved Cycles
        # scene is also an explicit quality choice unless its look says otherwise.
        volume = any(
            n.type in ("OUTPUT_MATERIAL", "OUTPUT_WORLD")
            and n.inputs.get("Volume")
            and n.inputs["Volume"].is_linked
            for owner in [*bpy.data.materials, *bpy.data.worlds]
            if owner.node_tree
            for n in owner.node_tree.nodes
        )
        engine = (
            a.engine
            if a.engine != "auto"
            else (
                tagged
                if tagged in ("cycles", "eevee")
                else "cycles"
                if volume or scene.render.engine == "CYCLES"
                else "eevee"
            )
        )
        renderer.set_engine(scene, engine)
        frames = renderer.frame_list(scene, a.frames)
        if frames[0] < 0 or scene.frame_step != 1 and not a.frames:
            raise RuntimeError(
                "finalize needs a contiguous nonnegative frame range; pass --frames START-END"
            )
        # blend_paths lists a file once per user (one texture can appear dozens of times); hash each once.
        files = sorted(
            {Path(bpy.path.abspath(p)).resolve() for p in bpy.utils.blend_paths(absolute=True)}
        )
        write(
            a.result,
            {
                "engine": engine,
                "frames": frames,
                "fps": renderer.frame_rate(scene.render),
                "samples": scene.cycles.samples
                if engine == "cycles"
                else scene.eevee.taa_render_samples,
                "eevee_samples": scene.eevee.taa_render_samples,
                "resolution_percent": scene.render.resolution_percentage,
                "resolution": [
                    scene.render.resolution_x * scene.render.resolution_percentage // 100,
                    scene.render.resolution_y * scene.render.resolution_percentage // 100,
                ],
                "dependencies": {str(p): digest(p) for p in files if p.is_file()},
            },
        )
        return
    if a.worker == "pack":
        sys.argv = ["pack_scene.py", "--", "--out", a.result, "--make-local"]
        runpy.run_path(
            str(Path(a.helper).with_name("pack_scene.py")), run_name="__main__"
        )
        return
    renderer.set_engine(scene, a.engine)
    if a.device == "cpu" and a.engine == "cycles":
        renderer.select_gpu = lambda s, allow: (
            setattr(s.cycles, "device", "CPU") or {"backend": "CPU", "devices": ["CPU"]}
        )
    if a.engine == "cycles":
        scene.cycles.use_denoising = True
    sys.argv = [
        "blender_render.py",
        "--",
        "--out",
        str(a.out),
        "--frames",
        a.frames,
        "--engine",
        a.engine,
        "--samples",
        str(a.samples),
        "--percent",
        str(a.percent),
        "--summary",
        a.result,
        "--denoiser",
        "oidn",
        "--png-compression",
        str(a.png_compression),
    ]
    if a.worker == "render":
        sys.argv.append("--resume")
    if a.allow_cpu:
        sys.argv.append("--allow-cpu")

    def render_once():
        try:
            renderer.main()
        except Exception:
            if not (
                a.allow_cpu and a.engine == "cycles" and scene.cycles.device == "GPU"
            ):
                raise
            print("Local Cycles GPU failed; retrying on CPU", file=sys.stderr)
            renderer.select_gpu = lambda s, allow: (
                setattr(s.cycles, "device", "CPU")
                or {"backend": "CPU", "devices": ["CPU fallback"]}
            )
            renderer.main()

    if a.worker == "probe":
        # Shader/kernel compilation belongs to startup, not every future frame.
        # Warm the same frame cheaply, then time it warm at low and at the scene's
        # real samples: the two give the fixed and the per-sample cost of a frame.
        sample_index = sys.argv.index("--samples") + 1
        result_index = sys.argv.index("--summary") + 1
        out_index = sys.argv.index("--out") + 1
        low = min(16, a.samples)
        warmup_result = str(a.result) + ".warmup.json"
        low_result = str(a.result) + ".low.json"
        sys.argv[sample_index] = str(low)
        sys.argv[result_index] = warmup_result
        render_once()
        sys.argv[result_index] = low_result
        sys.argv[out_index] = str(a.out) + "-low"
        render_once()
        sys.argv[sample_index] = str(a.samples)
        sys.argv[result_index] = a.result
        sys.argv[out_index] = str(a.out)
        render_once()
        result = read(a.result)
        result["cold_probe_seconds"] = read(warmup_result)["seconds_total"]
        result["low_seconds"] = read(low_result)["seconds_per_frame"]
        result["low_samples"] = low
        result["probe_method"] = (
            "same frame: cold low-sample warmup, warm low samples, warm desired samples"
        )
        write(a.result, result)
        return
    render_once()


# Seconds of one blender call: short calls keep finished frames if a call is stopped
# (an interrupted remote session syncs only finished calls) and let the deadline be checked.
CHUNK_SECONDS = 8 * 60
FLOOR_SAMPLES = {"cycles": 16, "eevee": 8}
MIN_PERCENT = 50


def interleaved(frames):
    # Every 8th frame (and the last) first, then every 4th, 2nd and the rest: whenever
    # time runs out the rendered frames cover the whole shot evenly.
    order = []
    for stride in (8, 4, 2, 1):
        for frame in [*frames[::stride], *([frames[-1]] if stride == 8 else [])]:
            if frame not in order:
                order.append(frame)
    return order


def fit(probe, samples, engine, frames, seconds):
    # A frame costs a fixed part (scene sync, volumes) plus a part per sample and pixel,
    # measured by two warm probes. Lower samples to the engine's floor, then resolution
    # (upscaled back on encode), to fit.
    per_sample = max(
        0.0,
        (probe["seconds"] - probe["low_seconds"])
        / max(samples - probe["low_samples"], 1),
    )
    fixed = max(0.0, probe["seconds"] - per_sample * samples)
    target = seconds / frames
    chosen = samples
    if fixed + per_sample * samples > target and per_sample:
        chosen = max(
            min(FLOOR_SAMPLES[engine], samples),
            min(samples, math.floor((target - fixed) / per_sample)),
        )
    percent = 100
    if fixed + per_sample * chosen > target:
        share = (target - fixed) / max(per_sample * chosen, 1e-6)
        percent = max(MIN_PERCENT, int(100 * math.sqrt(max(share, 0)) // 5 * 5))
    return chosen, percent, frames * (fixed + per_sample * chosen * (percent / 100) ** 2)


def probe_result(result):
    return {
        "seconds": result["seconds_per_frame"],
        "low_seconds": result["low_seconds"],
        "low_samples": result["low_samples"],
    }


def clock(epoch):
    return time.strftime("%H:%M", time.localtime(epoch))

"""Apply captured limb directions plus authored scene motion to a Rigify fixture.
Loads an existing .blend; writes a new checkpoint. Scene units are authored meters.
"""

import argparse
import hashlib
import importlib.util
import json
import math
import shlex
from pathlib import Path
import sys
import bpy
from mathutils import Quaternion, Vector

sys.dont_write_bytecode = True
spec = importlib.util.spec_from_file_location(
    "reference", Path(__file__).with_name("reference-rig.py")
)
reference = importlib.util.module_from_spec(spec)
spec.loader.exec_module(reference)
spec = importlib.util.spec_from_file_location(
    "fixture", Path(__file__).with_name("rigify-fixture.py")
)
fixture = importlib.util.module_from_spec(spec)
spec.loader.exec_module(fixture)
spec = importlib.util.spec_from_file_location(
    "motion_filter", Path(__file__).with_name("motion-filter.py")
)
motion_filter = importlib.util.module_from_spec(spec)
spec.loader.exec_module(motion_filter)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("motion", type=Path)
    parser.add_argument("plan", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--render", help="Comma-separated frame numbers or inclusive start:end")
    args = parser.parse_args(sys.argv[sys.argv.index("--") + 1 :])
    if not bpy.data.filepath or args.output.exists():
        raise ValueError("Load the supported character .blend and choose a new output path")
    rigs = [o for o in bpy.data.objects if o.type == "ARMATURE"]
    if len(rigs) != 1:
        raise ValueError("Expected one Rigify basic-human armature")
    rig = rigs[0]
    validate_rig(rig)
    rows, frames = reference.read_motion(args.motion)
    plan = json.loads(args.plan.read_text())
    if plan.get("source_sha256", rows[0]["source_sha256"]) != rows[0]["source_sha256"]:
        raise ValueError("Scene plan belongs to another source video")
    duration = rows[-1]["duration_seconds"]
    validate_plan(plan, duration, rig)
    scene = bpy.context.scene
    scene.render.fps, scene.render.fps_base = 30, 1
    scene.frame_end = math.ceil(duration * 30)
    root = empty("Authored_Root")
    rig.parent = root
    root_keys = plan["root"]
    if plan.get("smooth_authored_paths"):
        times = sorted({k["time"] for k in root_keys} | {f / 30 for f in range(scene.frame_end)})
        yaw_keys = [{"time": k["time"], "position": [k.get("yaw", 0), 0, 0]} for k in root_keys]
        root_keys = [
            {
                "time": t,
                "position": motion_filter.interpolate(root_keys, t),
                "yaw": motion_filter.interpolate(yaw_keys, t)[0],
            }
            for t in times
        ]
    for key in root_keys:
        root.location = key["position"]
        root.rotation_euler.z = math.radians(key.get("yaw", 0))
        root.keyframe_insert("location", frame=1 + key["time"] * 30)
        root.keyframe_insert("rotation_euler", frame=1 + key["time"] * 30)
    root.animation_data.action.name = "Authored_Room_Travel_Height"
    linear_keys(root.animation_data.action)
    for prop in plan.get("props", []):
        bpy.ops.mesh.primitive_cube_add(size=1, location=prop["position"])
        obj = bpy.context.object
        obj.name, obj.dimensions = prop["name"], prop["size"]
        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
        obj.color = (0.5, 0.3, 0.15, 1)
    contacts = []
    for index, c in enumerate(plan.get("contacts", [])):
        target = empty("Contact_%02d_%s" % (index, c["bone"]))
        target.location = c["position"]
        if c.get("object"):
            target.parent = bpy.data.objects[c["object"]]
        bone = rig.pose.bones[c["bone"]]
        constraint = bone.constraints.new("COPY_TRANSFORMS" if "rotation" in c else "COPY_LOCATION")
        if "rotation" in c:
            target.rotation_euler = [math.radians(v) for v in c["rotation"]]
        constraint.name = target.name
        constraint.target = target
        constraint.owner_space = constraint.target_space = "WORLD"
        constraint.influence = 0
        contacts.append((c, target, constraint))
    warnings = []
    repaired_frames = []
    if plan.get("smoothing", {}).get("repair_gap_seconds"):
        frames, repaired_frames = motion_filter.repair_gaps(
            frames, plan["smoothing"]["repair_gap_seconds"]
        )
    # Long gaps require an explicit review entry; they remain in the report and
    # original observations. Contacts/overrides do not turn them into measurements.
    for f in frames:
        if f["world"] is None:
            raise ValueError("Missing whole-body observation; trim or re-record")
        for joint in (7, 8, 11, 12, 13, 14, 15, 16, 23, 24, 25, 26, 27, 28):
            if min(f["world"][joint][3:]) < 0.25:
                if not any(
                    joint in c["joints"] and c["start"] <= f["seconds"] <= c["end"]
                    for c in plan.get("reviewed_occlusions", [])
                ):
                    raise ValueError(
                        f"Low confidence joint {joint} at {f['seconds']:.3f}s; review or trim before retargeting"
                    )
                warnings.append({"time": f["seconds"], "joint": joint})
    for side in ("L", "R"):
        for limb in ("upper_arm", "thigh"):
            parent = rig.pose.bones[limb + "_parent." + side]
            parent["IK_FK"] = 0
            parent["IK_Stretch"] = 0
            parent["pole_vector"] = True
    for bone in rig.pose.bones:
        bone.ik_stretch = 0
        for constraint in bone.constraints:
            if constraint.type == "IK":
                constraint.use_stretch = False
    previous = {}
    for f in frames:
        frame_time = 1 + f["seconds"] * 30
        scene.frame_set(math.floor(frame_time), subframe=frame_time % 1)
        heading = Quaternion((0, 0, 1), -math.radians(plan.get("source_yaw_degrees", 0)))
        p = [heading @ Vector((v[0], v[2], -v[1])) for v in f["world"]]
        hips = (p[23] + p[24]) / 2
        up = (p[11] + p[12]) / 2 - hips
        # The source establishes lean; room heading is a separate authored curve.
        torso = rig.pose.bones["torso"]
        torso.rotation_mode = "QUATERNION"
        torso.rotation_quaternion = Vector((0, 0, 1)).rotation_difference(up.normalized())
        key_pose(torso, 1 + f["seconds"] * 30, previous)
        bpy.context.view_layer.update()
        for side, shift in (("L", 0), ("R", 1)):
            for kind, joints, upper, lower, control, pole in (
                ("leg", (23, 25, 27), "thigh", "shin", "foot_ik", "thigh_ik_target"),
                ("arm", (11, 13, 15), "upper_arm", "forearm", "hand_ik", "upper_arm_ik_target"),
            ):
                a, b, c = [p[j + shift] for j in joints]
                if min((b - a).length, (c - b).length) < 1e-5:
                    raise ValueError("Degenerate captured limb")
                start = rig.pose.bones["ORG-" + upper + "." + side].head.copy()
                lengths = [
                    rig.data.bones["ORG-" + name + "." + side].length for name in (upper, lower)
                ]
                middle = start + (b - a).normalized() * lengths[0]
                end = middle + (c - b).normalized() * lengths[1]
                name = control + "." + side
                bone = rig.pose.bones[name]
                matrix = bone.bone.matrix_local.copy()
                matrix.translation = end
                # Flat foot orientation is authored; toes are not tracked reliably.
                if kind == "arm":
                    direction = (c - b).normalized()
                    rest = bone.bone.tail_local - bone.bone.head_local
                    matrix = (
                        rest.rotation_difference(direction).to_matrix().to_4x4()
                        @ bone.bone.matrix_local
                    )
                    matrix.translation = end
                bone.matrix = matrix
                bpy.context.view_layer.update()
                key_pose(bone, 1 + f["seconds"] * 30, previous)
                axis = (end - start).normalized()
                bend = middle - start - axis * (middle - start).dot(axis)
                if bend.length < 0.02:
                    bend = Vector((0, -1 if kind == "leg" else 1, 0))
                target = rig.pose.bones[pole + "." + side]
                matrix = target.bone.matrix_local.copy()
                matrix.translation = middle + bend.normalized() * 0.6
                target.matrix = matrix
                bpy.context.view_layer.update()
                key_pose(target, 1 + f["seconds"] * 30, previous)
    raw = rig.animation_data.action
    raw.name = "Captured_Controls"
    raw.use_fake_user = True
    linear_keys(raw)
    cleaned = raw.copy()
    cleaned.name = "Cleaned_Controls_Contacts"
    cleaned.use_fake_user = True
    rig.animation_data.action = cleaned
    if plan.get("smoothing"):
        motion_filter.smooth_controls(rig, scene, frames, plan["smoothing"])
    if "lean_limit_degrees" in plan:
        torso = rig.pose.bones["torso"]
        for f in frames:
            time = 1 + f["seconds"] * 30
            scene.frame_set(math.floor(time), subframe=time % 1)
            axis, angle = torso.rotation_quaternion.to_axis_angle()
            torso.rotation_quaternion = Quaternion(
                axis, min(angle, math.radians(plan["lean_limit_degrees"]))
            )
            torso.keyframe_insert("rotation_quaternion", frame=time, group="Authored lean limit")
    # Author control positions independently of capture, e.g. occluded seated feet.
    for override in plan.get("overrides", []):
        bone = rig.pose.bones[override["bone"]]
        path = bone.path_from_id("location")
        for layer in cleaned.layers:
            for strip in layer.strips:
                for bag in strip.channelbags:
                    for curve in bag.fcurves:
                        if curve.data_path == path:
                            for index in reversed(range(len(curve.keyframe_points))):
                                key = curve.keyframe_points[index]
                                if (
                                    1 + override["keys"][0]["time"] * 30
                                    <= key.co.x
                                    <= 1 + override["keys"][-1]["time"] * 30
                                ):
                                    curve.keyframe_points.remove(key, fast=True)
                            curve.update()
        for frame in range(1, scene.frame_end + 1):
            t = (frame - 1) / 30
            if not override["keys"][0]["time"] <= t <= override["keys"][-1]["time"]:
                continue
            scene.frame_set(frame)
            world = (
                motion_filter.interpolate(override["keys"], t)
                if plan.get("smooth_authored_paths")
                else interpolate(override["keys"], t)
            )
            matrix = bone.matrix.copy()
            matrix.translation = rig.matrix_world.inverted() @ world
            bone.matrix = matrix
            bpy.context.view_layer.update()
            bone.keyframe_insert("location", frame=frame, group="Authored " + bone.name)
    for c, target, constraint in contacts:
        times = {0, c["start"], c["start"] + c["blend"], c["end"] - c["blend"], c["end"], duration}
        if plan.get("smoothing"):
            times |= {f / 30 for f in range(scene.frame_end) if c["start"] <= f / 30 <= c["end"]}
        for time in sorted(times):
            weight = max(
                0, min(1, (time - c["start"]) / c["blend"], (c["end"] - time) / c["blend"])
            )
            constraint.influence = (
                weight * weight * (3 - 2 * weight) if plan.get("smoothing") else weight
            )
            constraint.keyframe_insert("influence", frame=1 + time * 30, group="Authored contacts")
    # Pole stabilization samples these curves before replacing its own keys.
    linear_keys(cleaned)
    pole_adjustments = (
        motion_filter.stabilize_poles(rig, scene, plan.get("overrides", []))
        if plan.get("smoothing")
        else None
    )
    linear_keys(cleaned)
    rig["source_sha256"] = rows[0]["source_sha256"]
    root["provenance"] = "Authored scene path and height; not recovered metric trajectory"
    scene["mocap_plan"] = json.dumps(plan)
    report = {
        "schema": "voyager.scene-motion/1",
        "source_sha256": rows[0]["source_sha256"],
        "duration": duration,
        "observations": len(frames),
        "authored": plan,
        "low_confidence_reviewed": warnings,
        "pole_adjustments": pole_adjustments,
        "interpolated_missing_pose_seconds": repaired_frames,
        "source_character": bpy.data.filepath,
        "actions": {},
    }
    report["blender_version"] = bpy.app.version_string
    report["plan_sha256"] = hashlib.sha256(args.plan.read_bytes()).hexdigest()
    report["character_sha256"] = hashlib.sha256(Path(bpy.data.filepath).read_bytes()).hexdigest()
    for action in (raw, cleaned):
        rig.animation_data.action = action
        # No influence curve in raw action: reset constraints explicitly before evaluating.
        for _, _, constraint in contacts:
            constraint.influence = 0
        report["actions"][action.name] = evaluate(rig, scene, contacts, plan)
    rig.animation_data.action = cleaned
    metrics = report["actions"][cleaned.name]
    report["checks"] = {
        "contacts_within_1cm": all(
            c["samples"] > 0 and c["max_error_m"] < 0.01 for c in metrics["contacts"]
        ),
        "feet_above_floor_within_5mm": metrics["foot_penetration_m"] < 0.005,
        "limb_lengths_within_0.1_percent": metrics["max_limb_length_error"] < 0.001,
        "flight_clears_floor": metrics["flight_min_sole_height_m"] is None
        or metrics["flight_min_sole_height_m"] > 0,
    }
    report["review_status"] = (
        "numeric checks passed; visual review required"
        if all(report["checks"].values())
        else "needs corrections"
    )
    staging(scene)
    scene.frame_set(1)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    bpy.ops.wm.save_as_mainfile(filepath=str(args.output.resolve()))
    args.output.with_suffix(".report.json").write_text(
        json.dumps(report, indent=2, allow_nan=False) + "\n"
    )
    if args.render:
        render = (
            range(int(args.render.split(":")[0]), int(args.render.split(":")[1]) + 1)
            if ":" in args.render
            else [int(f) for f in args.render.split(",")]
        )
        folder = args.output.parent / (args.output.stem + "-frames")
        for frame in render:
            if not scene.frame_start <= frame <= scene.frame_end:
                raise ValueError("Render frame outside clip")
            scene.frame_set(frame)
            scene.render.filepath = str(folder / f"{frame:04d}.png")
            bpy.ops.render.render(write_still=True)
        if ":" in args.render:
            # A range is a sequence: one verified video replaces its frames.
            print(
                json.dumps(
                    {
                        "frames": str(folder),
                        "finalize": f"voyager blender finalize {shlex.quote(str(folder))} --fps 30",
                    }
                )
            )


def linear_keys(action):
    # Blender 5.2 keyframe_insert ignores the new-key interpolation preference.
    for layer in action.layers:
        for strip in layer.strips:
            for bag in strip.channelbags:
                for curve in bag.fcurves:
                    for point in curve.keyframe_points:
                        point.interpolation = "LINEAR"


def validate_rig(rig):
    if (
        rig.get("mocap_adapter") != "rigify-basic-human/1"
        or (rig.animation_data and (rig.animation_data.action or rig.animation_data.nla_tracks))
        or rig.parent
        or any(abs(rig.matrix_world[i][j] - int(i == j)) > 1e-5 for i in range(4) for j in range(4))
    ):
        raise ValueError(
            "Unsupported rig: use an unanimated Rigify fixture with identity transform"
        )
    if rig.get("mocap_signature") != fixture.rig_signature(rig):
        raise ValueError(
            "Rig rest matrices, hierarchy or constraints differ from its fixture signature"
        )
    # Rest geometry and hierarchy, not just labels, define this narrow adapter.
    for side, sign in (("L", 1), ("R", -1)):
        for name, position in (
            ("thigh_fk", (sign * 0.098, 0.0124, 1.072)),
            ("hand_ik", (sign * 0.6594, 0.0492, 1.3061)),
            ("foot_ik", (sign * 0.098, 0.0162, 0.0852)),
        ):
            bone = rig.data.bones.get(name + "." + side)
            if not bone or (bone.head_local - Vector(position)).length > 0.001 or not bone.parent:
                raise ValueError("Unsupported Rigify rest geometry")


def validate_plan(plan, duration, rig):
    if plan.get("schema") != "voyager.scene-plan/1":
        raise ValueError("Unsupported scene plan")

    def keys_valid(keys):
        return (
            len(keys) >= 2
            and all(
                0 <= k["time"] <= duration
                and len(k["position"]) == 3
                and all(math.isfinite(v) for v in k["position"])
                and math.isfinite(k.get("yaw", 0))
                for k in keys
            )
            and all(a["time"] < b["time"] for a, b in zip(keys, keys[1:]))
        )

    if (
        not keys_valid(plan["root"])
        or plan["root"][0]["time"] != 0
        or plan["root"][-1]["time"] != duration
    ):
        raise ValueError("Root keys must cover the clip and increase")
    if not math.isfinite(plan.get("source_yaw_degrees", 0)):
        raise ValueError("Source yaw must be finite degrees")
    if "lean_limit_degrees" in plan and not 0 < plan["lean_limit_degrees"] <= 90:
        raise ValueError("Lean limit must be between 0 and 90 degrees")
    if "smoothing" in plan:
        settings = plan["smoothing"]
        if not isinstance(settings, dict) or any(
            k not in ("sigma_seconds", "pole_sigma_seconds", "repair_gap_seconds")
            or not isinstance(v, (int, float))
            or not 0.01 <= v <= 0.25
            for k, v in settings.items()
        ):
            raise ValueError("Smoothing widths must be between 0.01 and 0.25 seconds")
    controls = {"torso", "hand_ik.L", "hand_ik.R", "foot_ik.L", "foot_ik.R"}
    props = {p["name"] for p in plan.get("props", [])}
    if len(props) != len(plan.get("props", [])) or any(n in bpy.data.objects for n in props):
        raise ValueError("Prop names must be unique and new")
    for prop in plan.get("props", []):
        if (
            any(
                len(prop[k]) != 3 or not all(math.isfinite(v) for v in prop[k])
                for k in ("position", "size")
            )
            or min(prop["size"]) <= 0
        ):
            raise ValueError("Invalid prop geometry")
    for flight in plan.get("flight", []):
        if not 0 <= flight["start"] < flight["end"] <= duration:
            raise ValueError("Invalid flight interval")
    for c in plan.get("contacts", []):
        if (
            c["bone"] not in controls
            or c["bone"] not in rig.pose.bones
            or not 0 <= c["start"] < c["end"] <= duration
            or not 0 < c["blend"] <= (c["end"] - c["start"]) / 2
            or len(c["position"]) != 3
            or not all(math.isfinite(v) for v in c["position"])
            or c.get("object")
            and c["object"] not in props
        ):
            raise ValueError("Invalid contact")
        if "rotation" in c and (
            len(c["rotation"]) != 3 or not all(math.isfinite(v) for v in c["rotation"])
        ):
            raise ValueError("Contact rotation must be three finite Euler degrees")
        if c["bone"].startswith("foot") and any(
            c["start"] < flight["end"] and c["end"] > flight["start"]
            for flight in plan.get("flight", [])
        ):
            raise ValueError("Foot contact overlaps authored flight")
    for a, c in enumerate(plan.get("contacts", [])):
        if any(
            c["bone"] == b["bone"] and c["start"] < b["end"] and c["end"] > b["start"]
            for b in plan.get("contacts", [])[a + 1 :]
        ):
            raise ValueError("Overlapping contacts on one control")
    for override in plan.get("overrides", []):
        if (
            override["bone"] not in controls
            or override["bone"] not in rig.pose.bones
            or not keys_valid(override["keys"])
        ):
            raise ValueError("Invalid authored control override")
    for c in plan.get("reviewed_occlusions", []):
        if (
            not c.get("reason")
            or not 0 <= c["start"] < c["end"] <= duration
            or any(j not in range(33) for j in c["joints"])
        ):
            raise ValueError("Occlusions require a bounded interval, joints and review reason")


def empty(name):
    obj = bpy.data.objects.new(name, None)
    bpy.context.collection.objects.link(obj)
    obj.empty_display_type, obj.empty_display_size = "SPHERE", 0.05
    return obj


def key_pose(bone, frame, previous):
    bone.rotation_mode = "QUATERNION"
    if bone.name in previous and bone.rotation_quaternion.dot(previous[bone.name]) < 0:
        bone.rotation_quaternion.negate()
    previous[bone.name] = bone.rotation_quaternion.copy()
    bone.keyframe_insert("location", frame=frame, group=bone.name)
    bone.keyframe_insert("rotation_quaternion", frame=frame, group=bone.name)


def interpolate(keys, time):
    for a, b in zip(keys, keys[1:]):
        if a["time"] <= time <= b["time"]:
            return Vector(a["position"]).lerp(
                Vector(b["position"]), (time - a["time"]) / (b["time"] - a["time"])
            )
    raise ValueError("Time outside authored keys")


def evaluate(rig, scene, contacts, plan):
    errors = [[] for _ in contacts]
    penetration = 0
    min_flight = []
    max_stretch = 0
    motion = {}
    feet = [
        o
        for o in rig.children
        if o.type == "MESH" and any(n in o.name for n in ("DEF-foot", "DEF-toe"))
    ]
    for frame in range(1, scene.frame_end + 1):
        scene.frame_set(frame)
        graph = bpy.context.evaluated_depsgraph_get()
        evaluated = rig.evaluated_get(graph)
        time = (frame - 1) / 30
        for i, (c, target, _) in enumerate(contacts):
            if c["start"] + c["blend"] <= time <= c["end"] - c["blend"]:
                name = c["bone"].replace("_ik", "")
                bone = evaluated.pose.bones["DEF-spine" if name == "torso" else "DEF-" + name]
                actual = evaluated.matrix_world @ (
                    (bone.head + bone.tail) / 2 if name == "torso" else bone.head
                )
                errors[i].append((actual - target.matrix_world.translation).length)
        bottom = min(
            (o.evaluated_get(graph).matrix_world @ v.co).z
            for o in feet
            for v in o.evaluated_get(graph).data.vertices
        )
        penetration = max(penetration, -bottom)
        if any(c["start"] < time < c["end"] for c in plan.get("flight", [])):
            min_flight.append(bottom)
        for side in ("L", "R"):
            for name in ("upper_arm", "forearm", "thigh", "shin", "hand"):
                bone = evaluated.pose.bones["ORG-" + name + "." + side]
                motion.setdefault(name + "." + side, []).append(
                    (bone.head.copy(), bone.matrix.to_quaternion())
                )
                max_stretch = max(
                    max_stretch, abs((bone.tail - bone.head).length / bone.bone.length - 1)
                )
    return {
        "contacts": [
            {
                "bone": c["bone"],
                "samples": len(errors[i]),
                "max_error_m": max(errors[i], default=None),
            }
            for i, (c, _, _) in enumerate(contacts)
        ],
        "foot_penetration_m": penetration,
        "max_limb_length_error": max_stretch,
        "flight_min_sole_height_m": min(min_flight, default=None),
        "flight_max_sole_height_m": max(min_flight, default=None),
        "joint_motion": motion_filter.motion_metrics(motion),
    }


def staging(scene):
    scene.render.engine = "BLENDER_WORKBENCH"
    scene.display.shading.light = "STUDIO"
    scene.display.shading.color_type = "MATERIAL"
    scene.display.shading.show_shadows = True
    scene.display.shading.show_cavity = True
    scene.world.color = (0.045, 0.06, 0.085)
    scene.render.resolution_x, scene.render.resolution_y = 800, 800
    scene.render.resolution_percentage = 100
    bpy.ops.mesh.primitive_plane_add(size=200)
    bpy.context.object.name = "Ground"
    bpy.ops.object.camera_add(location=(3.8, -6, 3))
    camera = bpy.context.object
    camera.rotation_euler = (
        (Vector((0, 0.3, 0.95)) - camera.location).to_track_quat("-Z", "Y").to_euler()
    )
    camera.data.type, camera.data.ortho_scale = "ORTHO", 3.8
    scene.camera = camera


