"""Small CC0 manifest; authenticated services and add-ons are never required."""

import hashlib
import json
import os
import tempfile
import urllib.request
from pathlib import Path

MANIFEST = json.loads(Path(__file__).with_name("assets.json").read_text())


def request(url):
    return urllib.request.urlopen(
        urllib.request.Request(
            url,
            headers={"User-Agent": "Voyager-Scatter/1.0 (Blender CC0 asset importer)"},
        ),
        timeout=90,
    )


def checksum(path):
    with path.open("rb") as handle:
        return hashlib.file_digest(handle, "md5").hexdigest()


def download(entry, destination):
    destination.parent.mkdir(parents=True, exist_ok=True)
    if destination.exists() and checksum(destination) == entry["md5"]:
        return
    # A unique temporary file keeps concurrent cache consumers from seeing partial data.
    fd, name = tempfile.mkstemp(dir=destination.parent, suffix=".part")
    try:
        digest = hashlib.md5()
        with os.fdopen(fd, "wb") as out, request(entry["url"]) as response:
            while chunk := response.read(1024 * 1024):
                out.write(chunk)
                digest.update(chunk)
        if digest.hexdigest() != entry["md5"]:
            raise ValueError("asset checksum mismatch: " + entry["url"])
        os.replace(name, destination)
    finally:
        if os.path.exists(name):
            os.unlink(name)


def fetch(asset, cache):
    folder = Path(cache).expanduser().resolve() / asset
    folder.mkdir(parents=True, exist_ok=True)
    metadata = folder / "files.json"
    if not metadata.exists():
        with request("https://api.polyhaven.com/files/" + asset) as response:
            payload = response.read()
        json.loads(payload)
        fd, temporary = tempfile.mkstemp(dir=folder, suffix=".json.part")
        try:
            with os.fdopen(fd, "wb") as handle:
                handle.write(payload)
            os.replace(temporary, metadata)
        finally:
            if os.path.exists(temporary):
                os.unlink(temporary)
    choices = json.loads(metadata.read_text())["blend"]
    resolution = min(choices, key=lambda value: int(value.rstrip("k")))
    entry = choices[resolution]["blend"]
    model = folder / (asset + ".blend")
    download(entry, model)
    for relative, item in entry.get("include", {}).items():
        target = (folder / relative).resolve()
        if not target.is_relative_to(folder.resolve()):
            raise ValueError("unsafe asset companion path: " + relative)
        download(item, target)
    provenance = {
        "asset": asset,
        "source": "https://polyhaven.com/a/" + asset,
        "license": MANIFEST["license"],
        "license_url": MANIFEST["license_url"],
        "resolution": resolution,
        "url": entry["url"],
        "md5": entry["md5"],
    }
    (folder / "provenance.json").write_text(json.dumps(provenance, indent=2))
    return model, provenance


def load_models(path, catalog=False):
    """Append complete authored LODs, excluding source-part sheets and alternate overlapping LODs."""
    import re

    import bpy
    from mathutils import Matrix, Vector

    existing_images = set(bpy.data.images)
    levels = {}
    with bpy.data.libraries.load(str(path), link=False) as (source, dest):
        if catalog:
            # Poly Haven tree libraries contain a modelling workbench, component sheets,
            # procedural generators and several complete LODs. Never join that entire file.
            pattern = re.compile(re.escape(path.stem) + r"(?:_[a-z])?_LOD(\d+)$")
            for name in source.objects:
                match = pattern.fullmatch(name)
                if match:
                    levels.setdefault(int(match[1]), []).append(name)
        if levels:
            preferred = MANIFEST.get("near_lod", {}).get(path.stem, 1)
            near_level = preferred if preferred in levels else min(levels)
            far_level = min(
                (level for level in levels if level > near_level), default=near_level
            )
            near_names = sorted(levels[near_level])
            far_names = sorted(levels[far_level]) if far_level != near_level else []
            dest.objects = near_names + far_names
        else:
            near_names, far_names = source.objects[:], []
            dest.objects = near_names[:]
    imported = [obj for obj in dest.objects if obj]
    for obj in imported:
        bpy.context.scene.collection.objects.link(obj)
    bpy.context.view_layer.update()
    depsgraph = bpy.context.evaluated_depsgraph_get()
    near, far = [], []
    for index, obj in enumerate(imported):
        if obj.type != "MESH" or obj.hide_render:
            continue
        mesh = bpy.data.meshes.new_from_object(
            obj.evaluated_get(depsgraph), depsgraph=depsgraph
        )
        mesh.transform(obj.matrix_world)
        copy = bpy.data.objects.new(obj.name + " specimen", mesh)
        copy["source_variant"] = re.sub(
            r"_LOD\d+$", "", (near_names + far_names)[index]
        )
        bpy.context.scene.collection.objects.link(copy)
        (near if index < len(near_names) else far).append(copy)
    if not near:
        raise ValueError("no renderable meshes in " + str(path))
    if not catalog and len(near) > 1:
        # A user's file describes one assembled asset; preserve its relative part transforms.
        bpy.ops.object.select_all(action="DESELECT")
        for obj in near:
            obj.select_set(True)
        bpy.context.view_layer.objects.active = near[0]
        bpy.ops.object.join()
        near = near[:1]
    for obj in near + far:
        remove_loose_vertices(obj.data)
        if not obj.data.vertices:
            raise ValueError("empty source mesh: " + obj.name)
        lo = Vector(tuple(min(v.co[i] for v in obj.data.vertices) for i in range(3)))
        hi = Vector(tuple(max(v.co[i] for v in obj.data.vertices) for i in range(3)))
        obj.data.transform(
            Matrix.Translation((-0.5 * (lo.x + hi.x), -0.5 * (lo.y + hi.y), -lo.z))
        )
    original_meshes = [obj.data for obj in imported if obj.type == "MESH"]
    for obj in imported:
        bpy.data.objects.remove(obj, do_unlink=True)
    for mesh in set(original_meshes):
        if mesh.users == 0:
            bpy.data.meshes.remove(mesh)
    for image in set(bpy.data.images) - existing_images:
        if image.source == "FILE" and not image.packed_file:
            try:
                image.pack()
            except RuntimeError as error:
                raise ValueError(
                    "could not pack asset texture " + image.filepath
                ) from error
    return near, far


def simplify(obj, ratio):
    import bpy

    copy = obj.copy()
    copy.data = obj.data.copy()
    copy.name = obj.name + " distant"
    bpy.context.scene.collection.objects.link(copy)
    bpy.context.view_layer.objects.active = copy
    modifier = copy.modifiers.new("Distant source simplification", "DECIMATE")
    modifier.ratio = ratio
    bpy.ops.object.modifier_apply(modifier=modifier.name)
    remove_loose_vertices(copy.data)
    bpy.context.scene.collection.objects.unlink(copy)
    return copy


def load_kit(kit, cache):
    import bpy

    paths, provenance = [], []
    custom = kit.startswith("custom:")
    if custom:
        root = Path(kit[7:]).expanduser().resolve()
        paths = sorted(root.glob("*.blend")) if root.is_dir() else [root]
        if not paths or any(p.suffix != ".blend" or not p.is_file() for p in paths):
            raise ValueError(
                "custom kit needs a .blend file or directory of .blend files"
            )
        provenance = [
            {"source": str(p), "license": "user-supplied; not asserted"} for p in paths
        ]
    else:
        if kit not in MANIFEST["kits"]:
            raise ValueError("unknown kit: " + kit)
        for asset in MANIFEST["kits"][kit]:
            path, record = fetch(asset, cache)
            paths.append(path)
            provenance.append(record)
    collection = bpy.data.collections.new("Scatter sources " + kit.split(":")[0])
    distant = bpy.data.collections.new(collection.name + " distant")
    distant.use_fake_user = True
    for path in paths:
        near, far = load_models(path, catalog=not custom)
        by_variant = {obj["source_variant"]: obj for obj in far}
        for model in near:
            low = by_variant.get(model["source_variant"])
            if low is None:
                low = simplify(model, 0.15)
            for obj, target in ((model, collection), (low, distant)):
                for parent in list(obj.users_collection):
                    parent.objects.unlink(obj)
                target.objects.link(obj)
    collection["scatter_lod_collection"] = distant.name
    return collection, provenance


def lod_collection(collection, ratio=0.15):
    import bpy

    existing = bpy.data.collections.get(collection.get("scatter_lod_collection", ""))
    if existing is not None:
        return existing
    result = bpy.data.collections.new(collection.name + " distant")
    result.use_fake_user = True
    for obj in collection.objects:
        result.objects.link(simplify(obj, ratio))
    collection["scatter_lod_collection"] = result.name
    return result


def forest_trees(cache):
    return load_kit("trees", cache)


def remove_loose_vertices(mesh):
    # Collapse decimation can preserve loose source vertices; they cost memory and distort bounds.
    import bmesh

    data = bmesh.new()
    data.from_mesh(mesh)
    bmesh.ops.delete(
        data, geom=[v for v in data.verts if not v.link_faces], context="VERTS"
    )
    data.to_mesh(mesh)
    data.free()
    mesh.update()
